const strategies = ['role', 'label', 'text', 'testId', 'placeholder', 'altText', 'title', 'id', 'name', 'class', 'css', 'xpath'];
const locatorOperators = ['equals', 'contains', 'notEquals', 'notContains', 'regex'];
