function esc(value = '') { return String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char])); }
function formatTime(value) { return value ? new Date(value).toLocaleString(window.I18N.intlLocale(), { hour12: false }) : '—'; }
function assetRoute(type){return type==='case'?'cases':type==='suite'?'suites':'flows';}
function versionBadges(owner){return `<span class="badge code">v${Number(owner.currentVersion||owner.version||1)} 最新</span>${owner.stableVersion?`<span class="badge visual">v${Number(owner.stableVersion)} Stable</span>`:''}`;}
function versionSelectorFields(owner,versions,prefix='run'){const rows=(versions?.versions||[]).filter(item=>item.lifecycle!=='archived');return `<div class="version-selector"><label>回放版本</label><label class="check-row"><input type="radio" name="${prefix}Policy" value="stable" ${owner.stableVersion?'checked':'disabled'}> 稳定版本 v${Number(owner.stableVersion||0)}（推荐用于回归）</label><label class="check-row"><input type="radio" name="${prefix}Policy" value="latest" ${owner.stableVersion?'':'checked'}> 最新版本 v${Number(owner.currentVersion||owner.version||1)}（适合调试）</label><label class="check-row"><input type="radio" name="${prefix}Policy" value="specific"> 指定版本 <select id="${prefix}Specific">${rows.map(item=>`<option value="${item.version}">v${item.version} · ${esc(item.status)} · ${item.stepCount} 步${item.description?` · ${esc(item.description)}`:''}</option>`).join('')}</select></label></div>`;}
function selectedVersion(node,prefix='run'){const policy=$(`input[name="${prefix}Policy"]:checked`,node)?.value||'latest';return {policy,...(policy==='specific'?{version:Number($(`#${prefix}Specific`,node).value)}:{})};}
const versionAssetFields={case:['editorMode','codeLanguage','accountRef','priority','tags','data','configOverrides','sources','sourceFiles','compliance','defaults','setupSteps','steps','teardownSteps'],suite:['description','caseIds','caseBindings','setupSteps','teardownSteps','sources','sourceFiles','sessionPolicy','accountRef','data','defaults'],flow:['description','parameters','safety','defaults','steps','sources','sourceFiles']};
function versionDraftBanner(type,id){if(!versionEditContext||versionEditContext.type!==type||versionEditContext.id!==id)return'';return `<div class="version-edit-banner"><div><strong>正在基于 v${versionEditContext.baseVersion} 创建新版本</strong><span>历史版本不会被修改；保存后将生成 v${versionEditContext.nextVersion}。</span></div><button class="btn small secondary cancel-version-edit">取消历史版本编辑</button></div>`;}
function versionSavePatch(type,id){return versionEditContext?.type===type&&versionEditContext.id===id?{baseVersion:versionEditContext.baseVersion,versionSource:'derived-edit',versionDescription:`基于 v${versionEditContext.baseVersion} 编辑`}:{};}
function finishVersionEdit(type,id){if(versionEditContext?.type===type&&versionEditContext.id===id)versionEditContext=null;}
async function editHistoricalVersion(type,owner,version,node){const snapshot=await api(`/api/${assetRoute(type)}/${owner.id}/versions/${version}`);const collection=type==='case'?state.cases:type==='suite'?state.suites:state.flows;const index=collection.findIndex(item=>item.id===owner.id);const draft={...collection[index]};for(const key of versionAssetFields[type])if(snapshot[key]!==undefined)draft[key]=structuredClone(snapshot[key]);collection[index]=draft;versionEditContext={type,id:owner.id,baseVersion:Number(version),nextVersion:Math.max(...owner.versions.map(item=>Number(item.version)))+1};node?.remove();toast(`已加载 v${version}，保存后创建新版本`);render();}
function versionPhaseSummary(item,type){const c=item.phaseCounts||{};if(type==='case')return `Setup ${c.setupSteps||0} · 测试步骤 ${c.steps||0} · Teardown ${c.teardownSteps||0}`;if(type==='suite')return `Setup ${c.setupSteps||0} · Teardown ${c.teardownSteps||0}`;return `${c.steps||0} 步`;}
function versionExecutionModeSummary(item,type){const phases=type==='case'?[['Case Setup','setupSteps'],['测试步骤','steps'],['Case Teardown','teardownSteps']]:type==='suite'?[['Suite Setup','setupSteps'],['Suite Teardown','teardownSteps']]:[['公共流程','steps']];return `<div class="version-execution-modes"><strong>默认回放方式</strong>${phases.map(([label,key])=>{const nativeAvailable=Boolean(item.nativePhases?.[key]),native=item.executionModes?.[key]==='native'&&nativeAvailable;return `<span class="version-mode ${native?'native':'visual'}"><b>${label}</b>：${native?'原生代码':'无代码步骤'}${!native&&nativeAvailable?'（可切换原生）':''}</span>`;}).join('')}</div>`;}
async function viewVersion(type,owner,version){const snapshot=await api(`/api/${assetRoute(type)}/${owner.id}/versions/${version}`);const phases=type==='case'?[['Case Setup','setupSteps'],['测试步骤','steps'],['Case Teardown','teardownSteps']]:type==='suite'?[['Suite Setup','setupSteps'],['Suite Teardown','teardownSteps']]:[['公共流程步骤','steps']];const node=modal(`<h2>${esc(owner.name)} · v${version}</h2><p class="muted">只读历史快照。需要修改时请使用“基于此版本编辑”。</p>${phases.map(([label,key])=>`<details class="version-snapshot"><summary>${label} · ${(snapshot[key]||[]).length} 步</summary><pre>${esc(JSON.stringify(snapshot[key]||[],null,2))}</pre></details>`).join('')}<details class="version-snapshot"><summary>JavaScript / Python</summary><pre>${esc(snapshot.sources?.javascript||snapshot.sources?.steps?.javascript||'')}</pre></details><div class="actions"><button class="btn secondary" data-close>关闭</button></div>`,true);$('[data-close]',node).onclick=()=>node.remove();}
async function compareVersion(type,owner,version){const [from,to]=await Promise.all([api(`/api/${assetRoute(type)}/${owner.id}/versions/${version}`),api(`/api/${assetRoute(type)}/${owner.id}/versions/${owner.currentVersion}`)]);const keys=versionAssetFields[type].filter(key=>JSON.stringify(from[key])!==JSON.stringify(to[key]));const count=key=>Array.isArray(from[key])||Array.isArray(to[key])?`${from[key]?.length||0} → ${to[key]?.length||0}`:'内容有变化';const node=modal(`<h2>版本对比 · v${version} → v${owner.currentVersion}</h2><p class="muted">按字段和生命周期阶段比较；步骤移动会保留步骤 ID。</p><div class="version-diff">${keys.map(key=>`<div><strong>${esc(key)}</strong><span>${count(key)}</span></div>`).join('')||'<p>两个版本内容完全相同。</p>'}</div><div class="actions"><button class="btn secondary" data-close>关闭</button></div>`,true);$('[data-close]',node).onclick=()=>node.remove();}
async function editVersionMetadata(type,owner,item,parent){const node=modal(`<h2>编辑 v${item.version} 版本说明</h2><p class="muted">版本是否稳定请使用“标记 Stable”管理，不再设置额外标签。</p><div class="field"><label>版本说明</label><textarea id="versionDescription">${esc(item.description||'')}</textarea></div><div class="actions"><button class="btn primary" id="saveVersionMetadata">保存</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#saveVersionMetadata',node).onclick=async()=>{await api(`/api/${assetRoute(type)}/${owner.id}/versions/${item.version}/metadata`,{method:'PATCH',body:JSON.stringify({description:$('#versionDescription',node).value.trim()})});node.remove();parent.remove();await refresh(true);openVersionHistory(type,(type==='case'?state.cases:type==='suite'?state.suites:state.flows).find(x=>x.id===owner.id));};}
async function manageVersionRemoval(type,owner,item,parent){const preview=await api(`/api/${assetRoute(type)}/${owner.id}/versions/${item.version}/delete-preview`);if(item.lifecycle!=='archived'){if(!preview.canArchive)return modal(`<h2>无法归档 v${item.version}</h2><div class="notice danger-text">${preview.archiveBlockers.map(esc).join('<br>')}</div><div class="actions"><button class="btn secondary" data-close>关闭</button></div>`).querySelector('[data-close]').onclick=function(){this.closest('.modal').remove();};if(!confirm(`归档 ${owner.name} v${item.version}？归档后默认列表和回放选择中不再显示。`))return;await api(`/api/${assetRoute(type)}/${owner.id}/versions/${item.version}/archive`,{method:'POST',body:'{}'});toast(`v${item.version} 已归档，可随时恢复`);}else{const node=modal(`<h2>永久删除 v${item.version}</h2>${preview.canDelete?`<div class="notice"><strong>该操作不可恢复。</strong>结构化步骤、JS/Python 和该版本登录态将被删除。</div><div class="field"><label>请输入 v${item.version} 确认</label><input id="deleteVersionConfirm"></div>`:`<div class="notice danger-text">${preview.deleteBlockers.map(esc).join('<br>')}</div>`}<div class="actions">${preview.canDelete?'<button class="btn danger" id="confirmDeleteVersion">永久删除</button>':''}<button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();if(preview.canDelete)$('#confirmDeleteVersion',node).onclick=async()=>{const confirmation=$('#deleteVersionConfirm',node).value.trim();await api(`/api/${assetRoute(type)}/${owner.id}/versions/${item.version}`,{method:'DELETE',body:JSON.stringify({confirmation})});node.remove();parent.remove();toast(`v${item.version} 已永久删除`);await refresh();};return;}parent.remove();await refresh(true);openVersionHistory(type,(type==='case'?state.cases:type==='suite'?state.suites:state.flows).find(x=>x.id===owner.id));}
async function openVersionHistory(type,owner){const versions=await api(`/api/${assetRoute(type)}/${owner.id}/versions`);owner={...owner,versions:versions.versions,currentVersion:versions.currentVersion,stableVersion:versions.stableVersion};const node=modal(`<div class="split"><div><h2>${esc(owner.name)} · 版本管理</h2><p class="muted">历史内容不可变；编辑旧版本会创建新版本。先归档，再永久删除。</p></div>${versionBadges(owner)}</div><div class="version-toolbar"><select id="versionLifecycle"><option value="active">当前版本</option><option value="all">全部版本</option><option value="archived">已归档</option></select><input id="versionSearch" placeholder="搜索版本号或说明"></div><div class="version-list"></div><div class="actions"><button class="btn secondary" data-close>关闭</button></div>`,true);const renderRows=()=>{const lifecycle=$('#versionLifecycle',node).value,q=$('#versionSearch',node).value.trim().toLowerCase();const rows=versions.versions.filter(item=>(lifecycle==='all'||item.lifecycle===lifecycle)&&( !q||`v${item.version} ${item.description}`.toLowerCase().includes(q)));$('.version-list',node).innerHTML=rows.map(item=>`<article class="version-row ${item.lifecycle==='archived'?'archived':''}"><div class="version-main"><div class="inline"><strong>v${item.version} · ${esc(item.status)}</strong>${item.isCurrent?'<span class="badge code">Latest</span>':''}${item.isStable?'<span class="badge visual">Stable</span>':''}${item.lifecycle==='archived'?'<span class="badge">已归档</span>':''}</div><p>${formatTime(item.createdAt)} · ${esc(item.source)} · 基于 v${item.baseVersion||'—'}<br>${versionPhaseSummary(item,type)}</p>${versionExecutionModeSummary(item,type)}<p>${item.changedScopes?.length?`<br>修改范围：${item.changedScopes.map(esc).join('、')}`:''}${item.description?`<br>${esc(item.description)}`:''}${item.referenceCount?`<br>引用：${item.referenceCount}`:''}</p></div><div class="actions"><button class="btn small secondary view-version" data-version="${item.version}">查看</button>${item.lifecycle!=='archived'?`<button class="btn small secondary compare-version" data-version="${item.version}">与最新版对比</button><button class="btn small secondary edit-version" data-version="${item.version}">基于此版本编辑</button><button class="btn small primary replay-version" data-version="${item.version}">回放</button>`:`<button class="btn small secondary restore-version" data-version="${item.version}">恢复</button>`}<button class="btn small secondary metadata-version" data-version="${item.version}">版本说明</button>${!item.isStable&&item.lifecycle!=='archived'?`<button class="btn small secondary mark-stable" data-version="${item.version}">标记 Stable</button>`:''}<button class="btn small danger remove-version" data-version="${item.version}">${item.lifecycle==='archived'?'永久删除':'归档'}</button></div></article>`).join('')||'<div class="empty"><h2>没有匹配版本</h2></div>';$$('.view-version',node).forEach(button=>button.onclick=()=>viewVersion(type,owner,Number(button.dataset.version)));$$('.compare-version',node).forEach(button=>button.onclick=()=>compareVersion(type,owner,Number(button.dataset.version)));$$('.edit-version',node).forEach(button=>button.onclick=()=>editHistoricalVersion(type,owner,Number(button.dataset.version),node));$$('.metadata-version',node).forEach(button=>button.onclick=()=>editVersionMetadata(type,owner,versions.versions.find(x=>x.version===Number(button.dataset.version)),node));$$('.restore-version',node).forEach(button=>button.onclick=async()=>{await api(`/api/${assetRoute(type)}/${owner.id}/versions/${button.dataset.version}/restore`,{method:'POST',body:'{}'});node.remove();toast(`v${button.dataset.version} 已恢复`);await refresh();});$$('.remove-version',node).forEach(button=>button.onclick=()=>manageVersionRemoval(type,owner,versions.versions.find(x=>x.version===Number(button.dataset.version)),node));$$('.mark-stable',node).forEach(button=>button.onclick=async()=>{if(!confirm(`将 v${button.dataset.version} 设为默认稳定版本？`))return;await api(`/api/${assetRoute(type)}/${owner.id}/versions/${button.dataset.version}/mark-stable`,{method:'POST',body:'{}'});node.remove();toast(`v${button.dataset.version} 已标记为 Stable`);await refresh();});$$('.replay-version',node).forEach(button=>button.onclick=()=>{const selector={policy:'specific',version:Number(button.dataset.version)};node.remove();const entry=versions.versions.find(item=>item.version===selector.version);if(type==='case')chooseFixedReplayMode(owner,entry,policy=>executeCaseVersion(owner,selector,policy),'any');else if(type==='suite')runSuite(owner,selector);else chooseFixedReplayMode(owner,entry,policy=>executeFlowVersion(owner,selector,{},policy),'steps');});};$('[data-close]',node).onclick=()=>node.remove();$('#versionLifecycle',node).onchange=renderRows;$('#versionSearch',node).oninput=renderRows;renderRows();}
async function chooseVersion(type,owner,onConfirm,options={}){const versions=await api(`/api/${assetRoute(type)}/${owner.id}/versions`);let executionPolicy='visual';const phase=options.phase||'steps';const selectedEntry=()=>{const selector=selectedVersion(node),version=selector.policy==='stable'?owner.stableVersion:selector.policy==='latest'?(owner.currentVersion||owner.version):selector.version;return versions.versions.find(item=>Number(item.version)===Number(version));};const node=modal(`<h2>选择回放版本与方式 · ${esc(owner.name)}</h2><p class="muted">原生回放代码适合复杂 iframe、弹窗和窗口；当前步骤执行你在无代码页面保存的修改。</p>${versionSelectorFields(owner,versions)}<div class="field"><label>回放方式</label><div class="execution-policy-grid replay-mode-grid"><button type="button" class="execution-policy" data-replay-mode="prefer-native"><strong>按原生代码回放（推荐）</strong><span>执行该版本可编辑的 Playwright 原生回放代码；缺少原生代码的生命周期阶段使用当前步骤</span></button><button type="button" class="execution-policy selected" data-replay-mode="visual"><strong>按当前步骤回放</strong><span>执行当前无代码步骤和断言</span></button></div><p class="muted" id="nativeAvailability"></p></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="confirmVersionRun">开始回放</button><button class="btn secondary" data-close>取消</button></div>`);const updateAvailability=()=>{const entry=selectedEntry();const phases=entry?.nativePhases||{};const hasNative=phase==='any'?Object.values(phases).some(Boolean):Boolean(phases[phase]);const nativeButton=$('[data-replay-mode="prefer-native"]',node);nativeButton.disabled=!hasNative;if(!hasNative&&executionPolicy==='prefer-native'){executionPolicy='visual';$$('[data-replay-mode]',node).forEach(button=>button.classList.toggle('selected',button.dataset.replayMode==='visual'));}$('#nativeAvailability',node).textContent=hasNative?'该版本保存了可直接执行的原生回放代码。':'该版本没有原生回放代码，将按当前无代码步骤回放。';};$$('[data-replay-mode]',node).forEach(button=>button.onclick=()=>{if(button.disabled)return;executionPolicy=button.dataset.replayMode;$$('[data-replay-mode]',node).forEach(item=>item.classList.toggle('selected',item===button));});$$(`input[name="runPolicy"]`,node).forEach(input=>input.onchange=updateAvailability);$('#runSpecific',node).onchange=updateAvailability;$('[data-close]',node).onclick=()=>node.remove();$('#confirmVersionRun',node).onclick=()=>{const selector=selectedVersion(node);node.remove();onConfirm(selector,executionPolicy);};updateAvailability();}
function chooseFixedReplayMode(owner,entry,onConfirm,phase='any'){let policy='visual';const phases=entry.nativePhases||{},hasNative=phase==='any'?Object.values(phases).some(Boolean):Boolean(phases[phase]);const node=modal(`<h2>选择回放方式 · ${esc(owner.name)} v${entry.version}</h2><div class="execution-policy-grid replay-mode-grid"><button type="button" class="execution-policy" data-fixed-mode="prefer-native" ${hasNative?'':'disabled'}><strong>按原生代码回放（推荐）</strong></button><button type="button" class="execution-policy selected" data-fixed-mode="visual"><strong>按当前步骤回放</strong></button></div><p class="muted">${hasNative?'该版本保存了可直接执行的原生回放代码。':'该版本没有原生回放代码，将按当前无代码步骤回放。'}</p><div class="actions"><button class="btn primary" id="fixedReplayConfirm">开始回放</button><button class="btn secondary" data-close>取消</button></div>`);$$('[data-fixed-mode]',node).forEach(button=>button.onclick=()=>{if(button.disabled)return;policy=button.dataset.fixedMode;$$('[data-fixed-mode]',node).forEach(item=>item.classList.toggle('selected',item===button));});$('[data-close]',node).onclick=()=>node.remove();$('#fixedReplayConfirm',node).onclick=()=>{node.remove();onConfirm(policy);};}
function formatDuration(ms = 0) { return ms < 1000 ? `${ms} ms` : window.I18N.t(`${(ms / 1000).toFixed(1)} 秒`); }
function toast(message, type = '') { const node = document.createElement('div'); node.className = `toast ${type}`; node.textContent = window.I18N.t(message); $('#toastRegion').append(node); setTimeout(() => node.remove(), 4500); }
async function api(path, options = {}) {
  const response = await fetch(path, { headers: { 'Content-Type': 'application/json' }, ...options }); const body = response.status === 204 ? null : await response.json();
  if (!response.ok) { const error = new Error(window.I18N.translateError(body?.code, body?.error || '操作失败')); error.status = response.status; error.code = body?.code; error.payload = body; throw error; } return body;
}
async function refresh(keepContent = false) { state = await api('/api/state');for(const testCase of state.cases||[])if(testCase.editorMode==='code'&&!testCase.setupSteps?.length&&!testCase.steps?.length&&!testCase.teardownSteps?.length&&testCase.caseKind==='standard')testCase.caseKind='legacy-code'; updateShell(); if (!keepContent) render(); }
function updateShell() { $('#planCount').textContent = state.plans.length; $('#suiteCount').textContent = state.suites.length; $('#caseCount').textContent = state.cases.length; $('#flowCount').textContent = state.flows.length; $('#runCount').textContent = state.runs.length; const completed = state.runs.filter(x => ['passed', 'failed'].includes(x.status)); const pass = completed.filter(x => x.status === 'passed').length; $('#navHealth').textContent = completed.length ? `${Math.round(pass / completed.length * 100)}%` : '—'; $$('.nav-link').forEach(x => x.classList.toggle('active', x.dataset.view === view)); }
function go(next, id) { if(next==='runs'){next='executions';executionTab='history';}if(next==='execute'){next='executions';executionTab='start';}versionEditContext=null;view = next; selectedPlanId = next==='plans'?id:undefined; selectedSuiteId = next==='suites'?id:undefined; selectedCaseId = next==='cases'?id:undefined; selectedFlowId = next==='flows'?id:undefined; updateShell(); render(); }
function pageHeading(title, breadcrumb = 'coupayWeb testing') { $('#pageTitle').textContent = title; $('#breadcrumb').textContent = breadcrumb; }
function statusBadge(status) { const labels = { passed: '通过', failed: '失败', running: '执行中', warning: '警告', skipped: '跳过', 'not-run': '未配置' }; return `<span class="status ${esc(status)}">${labels[status] || esc(status || '未知')}</span>`; }
const pageOperations = new Set(['goto','reload','back','forward','waitForURL','waitForLoadState','waitForTimeout','scrollDown','scrollUp','scrollLeft','scrollRight','scrollToTop','scrollToBottom','newPage','switchPage','closePage','switchFrame','switchMainFrame','pageScreenshot','keyboardType','keyDown','keyUp','mouseMove','mouseDown','mouseUp','mouseClick','toHaveURL','toHaveTitle','toHavePageCount','toHaveDownloadFilename','toHaveDialogMessage','toHaveResponseStatus','toHaveStoredValue']);
const noValueOperations = new Set(['click','rightClick','dblclick','tap','hover','focus','clear','selectText','check','uncheck','chooseRadio','scrollToElement','switchMainFrame','mouseDown','mouseUp','toBeVisible','toBeHidden','toBeAttached','toBeEnabled','toBeDisabled','toBeEditable','toBeEmpty','toBeFocused','toBeInViewport','toBeChecked']);
const namedExpectationOperations = new Set(['toHaveAttribute','toHaveCSS','toHaveJSProperty']);
const targetOperations = new Set(['dragTo','selectAutocompleteOption']);
const dialogOperations = new Set(['acceptDialog','dismissDialog']);
function operationLabels(value){return ({rightClick:'右键点击',tap:'移动端 Tap',selectText:'选中文字',setInputFiles:'上传文件',chooseRadio:'选择单选项',setSliderValue:'设置滑块值',scrollDown:'向下滚动',scrollUp:'向上滚动',scrollLeft:'向左滚动',scrollRight:'向右滚动',scrollToElement:'滚动到元素',scrollToTop:'滚动到顶部',scrollToBottom:'滚动到底部',swipeLeft:'向左滑动',swipeRight:'向右滑动',swipeUp:'向上滑动',swipeDown:'向下滑动',dragTo:'拖拽到元素',acceptDialog:'触发并接受弹窗',dismissDialog:'触发并拒绝弹窗',clickAndSwitchPage:'点击并切换新窗口',newPage:'打开新窗口',switchPage:'切换窗口',closePage:'关闭当前窗口',clickAndWaitForDownload:'点击并等待下载',pageScreenshot:'保存页面截图',elementScreenshot:'保存元素截图',switchFrame:'进入 Frame',switchMainFrame:'返回主页面',selectAutocompleteOption:'选择自动补全项',expandTreeNode:'展开树节点',collapseTreeNode:'折叠树节点',selectGridRow:'选择表格行',extractText:'提取文本到变量',keyboardType:'键盘输入',keyDown:'按下按键',keyUp:'释放按键',mouseMove:'移动鼠标',mouseDown:'按下鼠标',mouseUp:'释放鼠标',mouseClick:'坐标点击',dispatchEvent:'触发 DOM 事件',toBeAttached:'已挂载到页面',toBeEditable:'可编辑',toBeEmpty:'内容为空',toBeFocused:'已获得焦点',toBeInViewport:'位于可视区域',toHaveValues:'选中值列表',toHaveAttribute:'属性值',toHaveClass:'完整 Class',toContainClass:'包含 Class',toHaveCSS:'CSS 样式',toHaveId:'元素 ID',toHaveJSProperty:'JavaScript 属性',toHaveAccessibleName:'可访问名称',toHaveAccessibleDescription:'可访问描述',toHaveAccessibleErrorMessage:'可访问错误信息',toHaveRole:'ARIA Role',toMatchAriaSnapshot:'ARIA 结构快照',toHavePageCount:'窗口数量',toHaveDownloadFilename:'下载文件名',toHaveDialogMessage:'弹窗消息',toHaveResponseStatus:'接口响应状态',toHaveStoredValue:'提取变量值'}[value]||value);}

function render() {
  if (view === 'dashboard') return renderDashboard();
  if (view === 'plans') return selectedPlanId ? renderPlanDetail() : renderPlans();
  if (view === 'suites') return selectedSuiteId ? renderSuiteDetail() : renderSuites();
  if (view === 'cases') return selectedCaseId ? renderCaseEditor() : renderCases();
  if (view === 'catalog') return renderCatalog();
  if (view === 'executions') return executionTab === 'history' ? renderRuns() : renderExecutionCenter();
  if (view === 'flows') return selectedFlowId ? renderFlowDetail() : renderFlows();
}
function renderDashboard() {
  pageHeading('概览'); const completed = state.runs.filter(x => ['passed', 'failed'].includes(x.status)); const passed = completed.filter(x => x.status === 'passed').length; const passRate = completed.length ? Math.round(passed / completed.length * 100) : 0; const latestFailed = state.runs.find(x => x.status === 'failed');
  $('#content').innerHTML = `<div class="hero"><div><h2>今天的测试状态</h2><p>从计划、用例到失败证据，都保存在这台电脑上。</p></div><button class="btn primary" id="dashNewPlan">${state.plans.length ? '新建测试计划' : '创建第一个测试计划'}</button></div>
    <div class="metrics"><div class="metric"><span>测试计划</span><strong>${state.plans.length}</strong><em>按顺序组织测试套件</em></div><div class="metric"><span>测试套件</span><strong>${state.suites.length}</strong><em>支持 Setup 和 Teardown</em></div><div class="metric"><span>测试用例</span><strong>${state.cases.length}</strong><em>${state.cases.filter(c=>c.editorMode==='code').length} 个代码用例</em></div><div class="metric"><span>公共流程</span><strong>${state.flows.length}</strong><em>可复用的场景步骤</em></div><div class="metric"><span>执行记录</span><strong>${state.runs.length}</strong><em>完整保留，可查询和删除</em></div><div class="metric"><span>通过率</span><strong>${passRate}%</strong><em>${passed} 通过 / ${completed.length} 已完成</em></div></div>
    <div class="grid-2"><div class="panel"><div class="panel-head"><div><h2>最近执行</h2><p>点击记录查看失败步骤和证据。</p></div><button class="btn small secondary" id="allRuns">查看全部</button></div><div class="list">${state.runs.slice(0,5).map(runRowHtml).join('') || emptyHtml('还没有执行记录','回放一个用例后，这里会显示结果。')}</div></div>
    <div class="panel"><div class="panel-head"><div><h2>${latestFailed ? '最近需要处理' : '工作台已就绪'}</h2><p>${latestFailed ? '优先修复最近一次失败。' : '从测试计划开始组织你的自动化。'}</p></div></div>${latestFailed ? diagnosticMini(latestFailed) : `<div class="empty"><h2>没有待处理失败</h2><p>运行测试计划后，失败用例会在这里给出原因和建议。</p></div>`}</div></div>`;
  $('#dashNewPlan').onclick = () => openPlanModal(); $('#allRuns').onclick = () => {executionTab='history';go('executions');}; bindRunRows();
}
function emptyHtml(title, text) { return `<div class="empty"><h2>${esc(title)}</h2><p>${esc(text)}</p></div>`; }
function diagnosticMini(run) { const diag = run.diagnostic || run.caseRuns?.find(x=>x.status==='failed')?.diagnostic; return `<div class="run-summary failure"><div class="split"><div><strong>${esc(run.caseName || run.planName || '执行失败')}</strong><p class="muted">${formatTime(run.startedAt)}</p></div>${statusBadge('failed')}</div><p>${esc(diag?.title || run.error || '有用例执行失败')}</p><button class="btn small secondary" data-run-open="${run.id}">查看诊断</button></div>`; }

function renderPlans() {
  pageHeading('测试计划'); $('#content').innerHTML = `<div class="hero"><div><h2>测试计划</h2><p>计划按顺序组织测试套件，套件再包含用例和生命周期。</p></div><button class="btn primary" id="pageNewPlan">新建计划</button></div><div class="plan-grid">${state.plans.map(plan => {const suites=(plan.suiteIds||[]).map(id=>state.suites.find(s=>s.id===id)).filter(Boolean);const count=suites.reduce((n,s)=>n+s.caseIds.length,0);return `<article class="plan-card" data-plan="${plan.id}"><h3>${esc(plan.name)}</h3><p>${esc(plan.description || '暂无计划说明')}</p><div class="plan-meta"><span>${suites.length} 个套件 · ${count} 个用例</span><span>更新于 ${formatTime(plan.updatedAt)}</span></div></article>`;}).join('') || emptyHtml('还没有测试计划','新建计划后，可以添加测试套件。')}</div>`;
  $('#pageNewPlan').onclick = () => openPlanModal(); $$('[data-plan]').forEach(node => node.onclick = () => go('plans', node.dataset.plan));
}
function renderPlanDetail() {
  const plan = state.plans.find(x => x.id === selectedPlanId); if (!plan) return go('plans'); const suites=(plan.suiteIds||[]).map(id=>state.suites.find(s=>s.id===id)).filter(Boolean); const cases=suites.flatMap(s=>s.caseIds).length;
  pageHeading(plan.name, '测试计划 / 详情'); $('#content').innerHTML = `<div class="panel summary-card"><div class="split"><div><h2>${esc(plan.name)}</h2><p>${esc(plan.description || '暂无说明')}</p></div><div class="actions"><button class="btn secondary" id="editPlan">编辑</button><button class="btn primary" id="runPlan" ${cases ? '' : 'disabled'}>运行整个计划</button><button class="btn danger" id="deletePlan">删除</button></div></div></div>
    <div id="planRunResult"></div><div class="panel"><div class="panel-head"><div><h2>计划中的测试套件</h2><p>执行顺序：Suite Setup → Case Setup/Steps/Teardown → Suite Teardown。</p></div><div class="actions"><button class="btn secondary" id="addExistingSuite">加入已有套件</button><button class="btn primary" id="createSuite">新建套件</button></div></div><div class="list">${suites.map(suiteRowHtml).join('') || emptyHtml('计划还是空的','新建或加入一个测试套件后即可运行。')}</div></div>`;
  $('#editPlan').onclick = () => openPlanModal(plan); $('#deletePlan').onclick = () => deletePlan(plan); $('#addExistingSuite').onclick = () => openAddSuite(plan); $('#createSuite').onclick = () => openSuiteModal(undefined,plan.id); $('#runPlan').onclick = () => runPlan(plan); bindSuiteRows();
}
function suiteRowHtml(suite){const plan=state.plans.find(item=>item.id===suite.planId);return `<article class="case-row" data-suite="${suite.id}"><div><h3>${esc(suite.name)}</h3><p>${esc(plan?.name||'未归档')} → ${suite.caseIds.length} 个用例 · Setup ${suite.setupSteps.length} 步 · Teardown ${suite.teardownSteps.length} 步</p></div><span class="badge visual">Suite</span><span class="muted">整套运行共享浏览器会话</span></article>`;}
function bindSuiteRows(){$$('[data-suite]').forEach(node=>node.onclick=()=>go('suites',node.dataset.suite));}
function renderSuites(){pageHeading('测试套件');$('#content').innerHTML=`<div class="hero"><div><h2>测试套件</h2><p>把同领域用例组织在一起，并配置套件级 Setup、Teardown。</p></div><button class="btn primary" id="pageNewSuite">新建测试套件</button></div><div class="list">${state.suites.map(suiteRowHtml).join('')||emptyHtml('还没有测试套件','新建套件后配置登录和退出登录。')}</div>`;$('#pageNewSuite').onclick=()=>openSuiteModal();bindSuiteRows();}
const suiteDataUsageGuide=()=>`<div class="data-guide-card"><div><strong>测试账号和测试数据怎么用？</strong><p>Suite 中的账号、数据和配置会传给子 Case；Case 的同名值优先。账号引用用于报告，页面输入值请在 JSON 中配置并通过变量引用。</p></div><button class="btn primary open-data-guide" type="button">查看示例与复制写法</button></div>`;
function nativeSourceEditorHtml(recorded,type,owner,phase){if(!recorded?.originalJavascript&&!recorded?.runnableJavascript)return '';const runnable=recorded.runnableJavascript||recorded.originalJavascript;return `<details class="technical recorded-source native-source" open><summary>原生回放 JavaScript（可编辑）</summary><p class="notice">这份代码供“按原生代码回放”执行。可删除登录前步骤或增加高级 Playwright 逻辑；保存会创建新版本，无代码步骤的修改不会覆盖它。</p><textarea class="code-editor native-runnable-code" spellcheck="false">${esc(runnable)}</textarea><div class="actions code-save-actions"><button class="btn primary save-native-source" type="button" data-native-type="${type}" data-native-id="${owner.id}" data-native-phase="${phase}" data-native-version="${Number(owner.currentVersion||owner.version||1)}">保存原生代码并创建新版本</button></div>${recorded.runnableEditedAt?`<p class="muted">原生回放代码上次编辑：${esc(formatTime(recorded.runnableEditedAt))}</p>`:''}<details class="immutable-recording"><summary>录制时原始快照（永久只读）</summary><p class="muted">用于审计和恢复，永远不会被无代码或原生代码编辑覆盖。</p><textarea class="code-editor" readonly>${esc(recorded.originalJavascript||'')}</textarea>${recorded.recordingFile?`<p class="muted break-anywhere">本地文件：${esc(recorded.recordingFile)}</p>`:''}</details></details>`;}
function recordedSourcesHtml(sources={},sourceFiles=[],recorded=null,type='',owner={},phase='steps'){if(!sources.javascript&&!sources.python&&!recorded?.originalJavascript&&!recorded?.runnableJavascript)return '';return `${nativeSourceEditorHtml(recorded,type,owner,phase)}${sources.javascript||sources.python?`<details class="technical recorded-source"><summary>查看无代码步骤生成的代码</summary><p class="muted">保存无代码步骤后，JavaScript 和 Python 会自动重建；不会覆盖原生回放代码或录制时原始快照。</p><div class="code-toolbar"><strong>JavaScript</strong></div><textarea class="code-editor" readonly>${esc(sources.javascript||'')}</textarea><div class="code-toolbar"><strong>Python</strong></div><textarea class="code-editor" readonly>${esc(sources.python||'')}</textarea>${sourceFiles.length?`<div class="code-toolbar"><strong>本地文件</strong></div><pre>${esc(JSON.stringify(sourceFiles,null,2))}</pre>`:''}</details>`:''}`;}
function lifecycleEditorHtml(owner,phase){const steps=owner[phase]||[];const recorded=owner.recordedSources?.[phase];const title=phase==='setupSteps'?'Suite Setup':'Suite Teardown';return `<div class="lifecycle-help"><div class="split"><strong>${title}</strong><button class="btn small secondary open-step-guide">步骤编写指南</button></div><p>${phase==='setupSteps'?'在本次套件开始时执行，例如登录；产生的登录态只在本次运行内传给各用例。':'无论 Setup 或用例是否失败都会执行，例如退出登录和清理数据。'}</p>${recorded?.runnableJavascript?'<p class="notice">此阶段保留了可编辑的原生回放代码。回放时可选择原生代码或当前无代码步骤。</p>':''}</div><div id="suitePhaseResult"></div><div class="actions phase-actions"><button class="btn secondary" id="recordSuitePhase">录制此阶段</button><button class="btn secondary" id="runSuitePhase" ${steps.length||recorded?.runnableJavascript?'':'disabled'}>回放此阶段</button><button class="btn secondary" id="insertSuiteFlow">插入公共流程</button><button class="btn primary" id="addSuiteStep">添加步骤</button></div><div id="steps" class="step-list">${steps.map(stepHtml).join('')||emptyHtml('还没有生命周期步骤','可以录制、添加普通步骤或插入公共流程。')}</div><div class="actions" style="margin-top:14px"><button class="btn primary" id="saveSuiteLifecycle">保存 ${title}</button></div>${recordedSourcesHtml(owner.sources?.[phase],owner.sourceFiles||[],recorded,'suite',owner,phase)}`;}
const suiteSettingsHtmlOriginal=suiteSettingsHtml;
suiteSettingsHtml=suite=>suiteDataUsageGuide()+suiteSettingsHtmlOriginal(suite);
function suiteSettingsHtml(suite){const proxy=suite.defaults?.proxy||{},mappings=proxy.mappings||[];return `<div class="data-guide-card"><div><strong>Suite 配置继承范围</strong><p>从本 Suite 或所属 Plan 执行时，下面的账号、数据、浏览器、代理和 Map Remote 会传给所有子用例；Case 的同名数据和配置覆盖 Suite。直接执行 Case 不继承 Suite。</p></div></div><div class="field-grid">${stabilitySettingsHtml(suite)}<div class="field"><label>浏览器</label><select id="browser"><option value="chromium">Chrome / Chromium</option><option value="firefox">Firefox</option><option value="webkit">WebKit</option></select></div><div class="field"><label>页面语言</label><input id="locale" value="${esc(suite.defaults?.locale||'zh-CN')}"></div><div class="field full"><label>起始 URL</label><input id="baseUrl" value="${esc(suite.defaults?.baseUrl||'')}" placeholder="https://qa.example.com"></div><div class="field"><label>Suite 测试账号引用</label><input id="accountRef" value="${esc(suite.accountRef||'')}" placeholder="accounts.coupay-suite-user"></div><div class="field"><label>上游代理服务器</label><input id="proxy" value="${esc(proxy.server||'')}" placeholder="http://127.0.0.1:8888"></div><div class="field full"><label>代理绕过域名</label><input id="proxyBypass" value="${esc(proxy.bypass||'')}" placeholder="localhost,127.0.0.1"></div><div class="field full"><label>Suite 测试数据 JSON</label><textarea id="data">${esc(JSON.stringify(suite.data||{},null,2))}</textarea><small>子 Case 可使用 <code>\${data.key}</code>；Case 同名键优先。</small></div><div class="field full"><div class="split"><label>Suite 远程映射（Map Remote）</label><button class="btn small secondary" id="addMapping" type="button">添加映射</button></div><div id="proxyMappings" class="mapping-list">${mappings.map(mappingRowHtml).join('')||'<p class="muted mapping-empty">还没有映射规则。</p>'}</div><small>套件执行及其子 Case 都会使用这些规则；Case 配置了映射时优先使用 Case 规则。</small></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="saveSuiteSettings">保存 Suite 配置与数据</button></div>`;}
function renderSuiteDetail(){const suite=state.suites.find(x=>x.id===selectedSuiteId);if(!suite)return go('suites');const cases=suite.caseIds.map(id=>state.cases.find(c=>c.id===id)).filter(Boolean);pageHeading(suite.name,'测试套件 / 编辑');let body=suitePhase==='cases'?`<div class="panel-head"><div><h2>套件中的用例</h2><p>从本 Suite 执行时，子用例继承 Suite 配置与数据。</p></div><button class="btn primary" id="addSuiteCase">加入用例</button></div><div class="list">${cases.map(caseRowHtml).join('')||emptyHtml('套件还没有用例','加入已有测试用例。')}</div>`:suitePhase==='settings'?suiteSettingsHtml(suite):lifecycleEditorHtml(suite,suitePhase);$('#content').innerHTML=`${versionDraftBanner('suite',suite.id)}<div class="panel summary-card"><div class="split"><div><h2>${esc(suite.name)} ${versionBadges(suite)}</h2><p>${esc(suite.description||'暂无说明')} · Suite 版本同时保存 Setup、Teardown、配置和子用例版本策略</p></div><div class="actions"><button class="btn secondary" id="suiteVersions">版本历史</button><button class="btn secondary" id="editSuite">编辑</button><button class="btn primary" id="runSuite" ${cases.length?'':'disabled'}>运行套件</button><button class="btn danger" id="deleteSuite">删除</button></div></div></div><div id="suiteRunResult"></div><div class="panel"><div class="tabs"><button class="tab ${suitePhase==='setupSteps'?'active':''}" data-suite-phase="setupSteps">Suite Setup</button><button class="tab ${suitePhase==='teardownSteps'?'active':''}" data-suite-phase="teardownSteps">Suite Teardown</button><button class="tab ${suitePhase==='cases'?'active':''}" data-suite-phase="cases">测试用例</button><button class="tab ${suitePhase==='settings'?'active':''}" data-suite-phase="settings">配置与数据</button></div>${body}</div>`;$$('[data-suite-phase]').forEach(btn=>btn.onclick=()=>{suitePhase=btn.dataset.suitePhase;renderSuiteDetail();});$('#suiteVersions').onclick=()=>openVersionHistory('suite',suite);$('#editSuite').onclick=()=>openSuiteModal(suite);$('#deleteSuite').onclick=()=>deleteSuite(suite);$('#runSuite').onclick=()=>runSuite(suite);if(suitePhase==='cases'){bindCaseRows();$('#addSuiteCase').onclick=()=>openAddCaseToSuite(suite);}else if(suitePhase==='settings'){$('#browser').value=suite.defaults?.browser||'chromium';$('#saveSuiteSettings').onclick=()=>saveSuiteSettings(suite);$('#stabilityPreset').onchange=applyStabilityPreset;$('#addMapping').onclick=()=>{const empty=$('.mapping-empty');if(empty)empty.remove();$('#proxyMappings').insertAdjacentHTML('beforeend',mappingRowHtml());bindMappingRows();};bindMappingRows();}else{bindSteps();$('#addSuiteStep').onclick=()=>appendStep();$('#recordSuitePhase').onclick=()=>openStructuredRecordDialog('suite',suite);$('#runSuitePhase').onclick=()=>runSuitePhase(suite);$('#insertSuiteFlow').onclick=()=>insertFlowCall();$('#saveSuiteLifecycle').onclick=()=>saveSuiteLifecycle(suite);} }
async function saveSuiteSettings(suite){let data;try{data=JSON.parse($('#data').value||'{}');}catch{return toast('Suite 测试数据不是有效 JSON','error');}const defaults={...suite.defaults,browser:$('#browser').value,locale:$('#locale').value.trim()||'zh-CN',baseUrl:$('#baseUrl').value.trim(),stability:{preset:$('#stabilityPreset').value,navigationTimeoutMs:Number($('#navigationTimeout').value||30000),actionTimeoutMs:Number($('#actionTimeout').value||10000),assertionTimeoutMs:Number($('#assertionTimeout').value||10000)},proxy:{...suite.defaults.proxy,mode:$('#proxy').value.trim()?'proxy':'direct',server:$('#proxy').value.trim(),bypass:$('#proxyBypass').value.trim(),mappings:collectMappings()}};await api(`/api/suites/${suite.id}`,{method:'PUT',body:JSON.stringify({...suite,...versionSavePatch('suite',suite.id),accountRef:$('#accountRef').value.trim(),data,defaults})});finishVersionEdit('suite',suite.id);toast('Suite 配置已保存，并已同步子用例本地代码');await refresh();}
function caseRowHtml(testCase) { const last = state.runs.find(r => r.caseId === testCase.id); return `<article class="case-row" role="button" tabindex="0" data-case="${testCase.id}" aria-label="打开测试用例 ${esc(testCase.name)}"><div><h3>${esc(testCase.name)} <span class="priority ${esc((testCase.priority||'P1').toLowerCase())}">${esc(testCase.priority||'P1')}</span></h3><p>${testCase.steps.length} 个步骤 · ${esc(testCase.defaults?.browser || 'chromium')} ${(testCase.tags||[]).map(tag=>`<span class="tag">${esc(tag)}</span>`).join(' ')}</p></div><span class="badge ${testCase.editorMode === 'code' ? 'code' : 'visual'}">${testCase.editorMode === 'code' ? '代码' : '无代码'}</span>${last ? statusBadge(last.status) : '<span class="muted">未执行</span>'}</article>`; }
function bindCaseRows() { $$('[data-case]').forEach(node => {node.onclick = () => go('cases', node.dataset.case);node.onkeydown=event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();node.click();}};}); }
async function runPlan(plan){let versionPolicy='stable',executionPolicy='default';const node=modal(`<h2>确认执行测试计划 · ${esc(plan.name)}</h2><p class="muted">这里只确认一次。计划内每个 Suite 仍使用一个浏览器会话、一段录像和一个 Trace。</p><div class="field-grid"><div class="field"><label>版本策略</label><select id="planVersionPolicy"><option value="stable">Stable 稳定版本（推荐）</option><option value="latest">Latest 最新版本</option></select></div><div class="field"><label>执行方式</label><select id="planExecutionPolicy"><option value="default">使用各阶段默认方式（推荐）</option><option value="prefer-native">优先按原生代码回放</option><option value="visual">全部按当前无代码步骤回放</option></select></div></div><div class="notice">新录制阶段默认使用原生回放代码；保存无代码修改后，该阶段默认使用当前步骤。缺少原生回放代码的历史阶段会自动使用当前步骤。</div><div class="actions"><button class="btn primary" id="confirmPlanRun">开始执行</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#confirmPlanRun',node).onclick=()=>{versionPolicy=$('#planVersionPolicy',node).value;executionPolicy=$('#planExecutionPolicy',node).value;node.remove();executePlanVersion(plan,{policy:versionPolicy},executionPolicy);};}
async function executePlanVersion(plan,versionSelector,executionPolicy='default') { const button = $('#runPlan'); if(button){button.disabled = true; button.textContent = '计划执行中…';} $('#planRunResult').innerHTML = '<div class="run-summary"><strong>正在按所选版本逐个执行，请不要关闭页面。</strong></div>'; try { const run = await api(`/api/plans/${plan.id}/run`, { method:'POST', body:JSON.stringify({ headless:false,versionSelector,executionPolicy }) }); $('#planRunResult').innerHTML = planRunResultHtml(run); toast('测试计划执行完成'); } catch (error) { const run = error.payload; $('#planRunResult').innerHTML = run?.caseRuns ? planRunResultHtml(run) : `<div class="run-summary failure">${esc(error.message)}</div>`; toast('测试计划存在失败用例','error'); } finally { if(button){button.disabled=false; button.textContent='运行整个计划';} await refresh(true); bindRunRows(); } }
function planRunResultHtml(run) { return `<div class="run-summary ${run.status==='passed'?'success':'failure'}"><div class="split"><strong>${run.status==='passed'?'计划全部通过':'计划执行完成，存在失败'}</strong>${statusBadge(run.status)}</div><p>${run.summary?.passed || 0} 通过 · ${run.summary?.failed || 0} 失败 · ${formatDuration(run.durationMs)}</p><button class="btn small secondary" data-run-open="${run.id}">在弹窗查看完整记录</button></div>${hierarchicalRunHtml(run,run.id)}`; }

function renderCases() {
  pageHeading('测试用例'); const orphans = state.cases.filter(c => !state.suites.some(s => s.caseIds.includes(c.id)));
  $('#content').innerHTML = `<div class="hero"><div><h2>测试用例</h2><p>无代码模式编辑步骤和期望值；代码模式在线编辑 Playwright JS/Python。</p></div><button class="btn primary" id="pageNewCase">新建测试用例</button></div><div class="panel"><div class="panel-head"><div><h2>全部用例</h2><p>${orphans.length} 个未加入测试计划。</p></div></div><div class="list">${state.cases.map(caseRowHtml).join('') || emptyHtml('还没有测试用例','选择无代码或代码模式创建第一个用例。')}</div></div>`;
  $('#pageNewCase').onclick = () => openCaseModal(); bindCaseRows();
}
function catalogCaseHtml(testCase){return `<article class="asset-row" data-catalog-case="${testCase.id}"><div><div class="inline"><strong>${esc(testCase.name)}</strong><span class="priority ${esc((testCase.priority||'P1').toLowerCase())}">${esc(testCase.priority||'P1')}</span>${(testCase.tags||[]).map(tag=>`<span class="tag">${esc(tag)}</span>`).join('')}</div><p>${testCase.steps.length} 个步骤 · ${esc(testCase.accountRef||'未设置账号')}</p></div><div class="actions"><button class="btn small secondary edit-case-meta" data-id="${testCase.id}">标签/优先级</button><button class="btn small primary open-catalog-case" data-id="${testCase.id}">打开</button></div></article>`;}
function renderCatalog(){pageHeading('资产查询','测试资产 / 查询');const tags=[...new Set(state.cases.flatMap(item=>item.tags||[]))].sort();$('#content').innerHTML=`<div class="hero"><div><h2>测试资产查询</h2><p>在同一页查询测试计划、测试套件和测试用例，并按优先级与标签筛选用例。</p></div></div><div class="panel catalog-filters"><input id="catalogQuery" placeholder="搜索名称、说明、账号或标签"><select id="catalogType"><option value="all">全部类型</option><option value="plan">测试计划</option><option value="suite">测试套件</option><option value="case">测试用例</option></select><select id="catalogPriority"><option value="">全部优先级</option><option>P0</option><option>P1</option><option>P2</option></select><select id="catalogTag"><option value="">全部标签</option>${tags.map(tag=>`<option>${esc(tag)}</option>`).join('')}</select></div><div id="catalogResults"></div>`;const update=()=>{const q=$('#catalogQuery').value.trim().toLowerCase(),type=$('#catalogType').value,priority=$('#catalogPriority').value,tag=$('#catalogTag').value;const match=value=>!q||String(value||'').toLowerCase().includes(q);const plans=state.plans.filter(item=>match(item.name)||match(item.description));const suites=state.suites.filter(item=>match(item.name)||match(item.description)||match(item.accountRef));const cases=state.cases.filter(item=>(!priority||item.priority===priority)&&(!tag||(item.tags||[]).includes(tag))&&(match(item.name)||match(item.accountRef)||(item.tags||[]).some(match)));$('#catalogResults').innerHTML=`${type==='all'||type==='plan'?`<section class="panel asset-section"><h2>测试计划 <span class="badge">${plans.length}</span></h2>${plans.map(item=>`<article class="asset-row"><div><strong>${esc(item.name)}</strong><p>${esc(item.description||'暂无说明')}</p></div><button class="btn small primary open-catalog-plan" data-id="${item.id}">打开</button></article>`).join('')||'<p class="muted">没有匹配计划</p>'}</section>`:''}${type==='all'||type==='suite'?`<section class="panel asset-section"><h2>测试套件 <span class="badge">${suites.length}</span></h2>${suites.map(item=>`<article class="asset-row"><div><strong>${esc(item.name)}</strong><p>${item.caseIds.length} 个用例 · ${esc(item.accountRef||'未设置套件账号')}</p></div><button class="btn small primary open-catalog-suite" data-id="${item.id}">打开</button></article>`).join('')||'<p class="muted">没有匹配套件</p>'}</section>`:''}${type==='all'||type==='case'?`<section class="panel asset-section"><h2>测试用例 <span class="badge">${cases.length}</span></h2>${cases.map(catalogCaseHtml).join('')||'<p class="muted">没有匹配用例</p>'}</section>`:''}`;$$('.open-catalog-plan').forEach(button=>button.onclick=()=>go('plans',button.dataset.id));$$('.open-catalog-suite').forEach(button=>button.onclick=()=>go('suites',button.dataset.id));$$('.open-catalog-case').forEach(button=>button.onclick=()=>go('cases',button.dataset.id));$$('.edit-case-meta').forEach(button=>button.onclick=()=>openCaseMetadata(state.cases.find(item=>item.id===button.dataset.id)));};['catalogQuery','catalogType','catalogPriority','catalogTag'].forEach(id=>$('#'+id).oninput=update);update();}
function openCaseMetadata(testCase){const node=modal(`<h2>编辑测试用例信息</h2><div class="field-grid"><div class="field full"><label>所属测试套件 *</label><select id="metaSuite"><option value="">请选择测试套件</option>${state.suites.map(suite=>{const plan=state.plans.find(item=>item.id===suite.planId);return`<option value="${suite.id}" ${suite.id===testCase.suiteId?'selected':''}>${esc(plan?.name||'未归档')} → ${esc(suite.name)}</option>`;}).join('')}</select><small>用例只能属于一个 Suite；变更后会移动用例并创建新的资产版本。</small></div><div class="field"><label>优先级</label><select id="metaPriority"><option>P0</option><option>P1</option><option>P2</option></select></div><div class="field full"><label>标签（逗号分隔）</label><input id="metaTags" value="${esc((testCase.tags||[]).join(', '))}" placeholder="CICD, stable, smoke"></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="saveMeta">保存</button><button class="btn secondary" data-close>取消</button></div>`);$('#metaPriority',node).value=testCase.priority||'P1';$('[data-close]',node).onclick=()=>node.remove();$('#saveMeta',node).onclick=async()=>{try{const suiteId=$('#metaSuite',node).value;if(!suiteId)throw new Error('请选择所属测试套件');const tags=$('#metaTags',node).value.split(',').map(item=>item.trim()).filter(Boolean);await api(`/api/cases/${testCase.id}`,{method:'PUT',body:JSON.stringify({...testCase,suiteId,priority:$('#metaPriority',node).value,tags})});node.remove();toast('用例归属、优先级和标签已保存');await refresh();}catch(error){toast(error.message,'error');}};}
function executionTabsHtml(){return `<div class="execution-tabs"><button class="execution-tab ${executionTab==='start'?'active':''}" data-execution-tab="start">▶ 发起执行</button><button class="execution-tab ${executionTab==='history'?'active':''}" data-execution-tab="history">☷ 执行记录 <b>${state.runs.length}</b></button></div>`;}
function bindExecutionTabs(){$$('[data-execution-tab]').forEach(button=>button.onclick=()=>{executionTab=button.dataset.executionTab;render();});}
function executionVersionValue(selector={policy:'stable'}){return selector.policy==='specific'?`specific:${Number(selector.version)}`:selector.policy||'stable';}
function parseExecutionVersion(value){const [policy,version]=String(value||'stable').split(':');return {policy,...(policy==='specific'?{version:Number(version)}:{})};}
function executionVersionOptions(owner,selector){const active=(owner.versions||[]).filter(item=>item.lifecycle!=='archived');const value=executionVersionValue(selector);return `<option value="stable" ${value==='stable'?'selected':''} ${owner.stableVersion?'':'disabled'}>Stable · v${Number(owner.stableVersion||0)}</option><option value="latest" ${value==='latest'?'selected':''}>Latest · v${Number(owner.currentVersion||owner.version||1)}</option>${active.map(item=>`<option value="specific:${item.version}" ${value===`specific:${item.version}`?'selected':''}>指定 v${item.version} · ${esc(item.status)}</option>`).join('')}`;}
function resolvedExecutionVersion(owner,selector){if(selector?.policy==='specific')return Number(selector.version);if(selector?.policy==='latest')return Number(owner.currentVersion||owner.version||1);return Number(owner.stableVersion||owner.currentVersion||owner.version||1);}
function selectedSuiteSnapshot(suite){const selector=executionSelection.suiteVersions.get(suite.id)||{policy:'stable'};const version=resolvedExecutionVersion(suite,selector);return {selector,version,snapshot:(suite.versions||[]).find(item=>Number(item.version)===version)?.snapshot||suite};}
function executionSuitesForPlan(planId){return state.suites.filter(item=>item.planId===planId);}
function executionCasesForSuite(suiteId){return state.cases.filter(item=>item.suiteId===suiteId);}
function setExecutionSuiteCascade(suiteId,checked){checked?executionSelection.suiteIds.add(suiteId):executionSelection.suiteIds.delete(suiteId);for(const testCase of executionCasesForSuite(suiteId)){checked?executionSelection.caseIds.add(testCase.id):executionSelection.caseIds.delete(testCase.id);}}
function setExecutionPlanCascade(planId,checked){checked?executionSelection.planIds.add(planId):executionSelection.planIds.delete(planId);for(const suite of executionSuitesForPlan(planId))setExecutionSuiteCascade(suite.id,checked);}
function recomputeExecutionPlan(planId){const suites=executionSuitesForPlan(planId);const all=suites.length>0&&suites.every(item=>executionSelection.suiteIds.has(item.id));all?executionSelection.planIds.add(planId):executionSelection.planIds.delete(planId);}
function recomputeExecutionSuite(suiteId){const suite=state.suites.find(item=>item.id===suiteId);if(!suite)return;const cases=executionCasesForSuite(suiteId);const all=cases.length>0&&cases.every(item=>executionSelection.caseIds.has(item.id));all?executionSelection.suiteIds.add(suiteId):executionSelection.suiteIds.delete(suiteId);recomputeExecutionPlan(suite.planId);}
function executionSuitePartial(suiteId){const cases=executionCasesForSuite(suiteId);const count=cases.filter(item=>executionSelection.caseIds.has(item.id)).length;return count>0&&count<cases.length;}
function executionPlanPartial(planId){const suites=executionSuitesForPlan(planId),cases=suites.flatMap(item=>executionCasesForSuite(item.id));const selectedSuites=suites.filter(item=>executionSelection.suiteIds.has(item.id)).length,selectedCases=cases.filter(item=>executionSelection.caseIds.has(item.id)).length;return !executionSelection.planIds.has(planId)&&(selectedSuites>0||selectedCases>0);}
function suiteSnapshotCaseIds(snapshot){return [...new Set([...(snapshot?.caseBindings||[]).map(item=>item.caseId),...(snapshot?.caseIds||[])])];}
function membershipSafeSuiteSelector(suite,selector,caseIds){const requestedVersion=resolvedExecutionVersion(suite,selector),requested=(suite.versions||[]).find(item=>Number(item.version)===requestedVersion),contains=entry=>caseIds.every(id=>suiteSnapshotCaseIds(entry?.snapshot).includes(id));if(contains(requested))return {selector};const fallback=(suite.versions||[]).filter(item=>item.lifecycle!=='archived'&&contains(item)).sort((a,b)=>Number(b.version)-Number(a.version))[0];if(fallback)return {selector:{policy:'specific',version:Number(fallback.version)},membershipFallback:{requestedPolicy:selector?.policy||'stable',requestedVersion,resolvedVersion:Number(fallback.version),caseIds:[...caseIds]}};return {selector,membershipError:{requestedPolicy:selector?.policy||'stable',requestedVersion,caseIds:[...caseIds]}};}
function executionPlanRow(plan){const active=executionSelection.activePlanId===plan.id;return `<article class="execution-tree-row ${active?'active':''} ${executionPlanPartial(plan.id)?'partial':''}" data-focus-plan="${plan.id}"><input type="checkbox" data-whole-plan="${plan.id}" ${executionSelection.planIds.has(plan.id)?'checked':''} aria-label="执行整个计划"><div><strong>${esc(plan.name)}</strong><small>${executionSuitesForPlan(plan.id).length} 个套件</small></div><span>›</span></article>`;}
function executionSuiteRow(suite){const active=executionSelection.activeSuiteId===suite.id;return `<article class="execution-tree-row ${active?'active':''} ${executionSuitePartial(suite.id)?'partial':''}" data-focus-suite="${suite.id}"><input type="checkbox" data-whole-suite="${suite.id}" ${executionSelection.suiteIds.has(suite.id)?'checked':''} aria-label="执行整个套件"><div><strong>${esc(suite.name)}</strong><small>${executionCasesForSuite(suite.id).length} 个用例 · v${resolvedExecutionVersion(suite,executionSelection.suiteVersions.get(suite.id))}</small></div><span>›</span></article>`;}
function executionCaseRow(testCase){return `<label class="execution-tree-row execution-case-row"><input type="checkbox" data-exec-case="${testCase.id}" ${executionSelection.caseIds.has(testCase.id)?'checked':''}><div><strong>${esc(testCase.name)}</strong><small>${esc(testCase.priority||'P1')} · ${esc((testCase.tags||[]).join(', ')||'无标签')}</small></div></label>`;}
function executionVersionPanel(suite){if(!suite)return '<div class="panel execution-version-panel"><h2>执行版本</h2><p class="muted">选择执行范围后，点击“执行已选择项目”选择 Stable 或 Latest。</p></div>';const covered=executionSelection.planIds.has(suite.planId)||executionSelection.suiteIds.has(suite.id);const selectedCases=executionCasesForSuite(suite.id).filter(item=>covered||executionSelection.caseIds.has(item.id));return `<section class="panel execution-version-panel execution-version-hint"><div><h2>执行版本在启动时统一选择</h2><p>点击“执行已选择项目”后，选择 Stable 稳定版本或 Latest 最新版本；策略会同时应用到所选 Suite 与 Case。</p></div><span class="badge code">${selectedCases.length} 个 Case</span><div class="notice"><strong>版本规则：</strong>Suite Setup 与 Suite Teardown 属于同一个 Suite 原子版本，不能拆成两个版本。只选择 Test Case 时仍会执行对应 Suite 的 Setup 和 Teardown，并保持同一个浏览器会话。</div><select id="execSuiteVersion" class="hidden">${executionVersionOptions(suite,{policy:'stable'})}</select>${selectedCases.map(testCase=>`<select class="hidden" data-exec-case-version="${testCase.id}">${executionVersionOptions(testCase,{policy:'stable'})}</select>`).join('')}</section>`;}
function buildExecutionSelections(policyOverride=null){const suites=new Map();const selectedPolicy=policyOverride?{policy:policyOverride}:null;const include=(suite,allCases,caseId)=>{let item=suites.get(suite.id);if(!item){item={suiteId:suite.id,planId:suite.planId,versionSelector:selectedPolicy||executionSelection.suiteVersions.get(suite.id)||{policy:'stable'},caseVersionSelector:selectedPolicy||{policy:'stable'},allCases:false,caseSelections:[]};suites.set(suite.id,item);}if(allCases){item.allCases=true;item.caseSelections=[];}else if(!item.allCases&&!item.caseSelections.some(entry=>entry.caseId===caseId))item.caseSelections.push({caseId,versionSelector:selectedPolicy||executionSelection.caseVersions.get(caseId)||{policy:'stable'}});};for(const planId of executionSelection.planIds){for(const suite of state.suites.filter(item=>item.planId===planId))include(suite,true);}for(const suiteId of executionSelection.suiteIds){const suite=state.suites.find(item=>item.id===suiteId);if(suite&&!executionSelection.planIds.has(suite.planId))include(suite,true);}for(const caseId of executionSelection.caseIds){const testCase=state.cases.find(item=>item.id===caseId);const suite=state.suites.find(item=>item.id===testCase?.suiteId);if(suite&&!executionSelection.planIds.has(suite.planId)&&!executionSelection.suiteIds.has(suite.id))include(suite,false,caseId);}return [...suites.values()].map(selection=>{if(selection.allCases)return selection;const suite=state.suites.find(item=>item.id===selection.suiteId),caseIds=selection.caseSelections.map(item=>item.caseId);if(!suite||!caseIds.length)return selection;const compatibility=membershipSafeSuiteSelector(suite,selection.versionSelector,caseIds);return {...selection,versionSelector:compatibility.selector,...(compatibility.membershipFallback?{membershipFallback:compatibility.membershipFallback}:{}),...(compatibility.membershipError?{membershipError:compatibility.membershipError}:{})};});}
function selectionRunHtml(run,includeEvidence=true){return `<div class="run-summary ${run.status==='passed'?'success':'failure'}"><div class="split"><strong>自定义执行${run.status==='passed'?'通过':'完成，存在失败'}</strong>${statusBadge(run.status)}</div><p>${run.summary.passed} 通过 · ${run.summary.failed} 失败 · ${run.summary.skipped} 跳过 · 共 ${run.summary.total} 个用例</p></div>${includeEvidence?(run.planRuns||[]).map(plan=>`<section class="execution-evidence"><h3>${esc(plan.planName)}</h3>${hierarchicalRunHtml(plan,run.id)}</section>`).join(''):''}`;}
function executionSnapshot(owner,selector){const version=resolvedExecutionVersion(owner,selector);return {version,snapshot:(owner.versions||[]).find(item=>Number(item.version)===version)?.snapshot||owner};}
function resolvedPreviewMode(snapshot,phase,executionPolicy='default'){const hasNative=Boolean(snapshot?.recordedSources?.[phase]?.runnableJavascript);if(executionPolicy==='visual')return {mode:'visual',fallback:false,hasNative};if(executionPolicy==='prefer-native')return {mode:hasNative?'native':'visual',fallback:!hasNative,hasNative};const preferred=snapshot?.executionModes?.[phase]||'visual';return {mode:preferred==='native'&&hasNative?'native':'visual',fallback:preferred==='native'&&!hasNative,hasNative};}
function previewModeHtml(snapshot,phase,executionPolicy='default'){const resolved=resolvedPreviewMode(snapshot,phase,executionPolicy),label=resolved.mode==='native'?'原生回放代码':'当前无代码步骤';return `<span class="execution-source ${resolved.mode}${resolved.fallback?' fallback':''}">${label}${resolved.fallback?'（无原生代码，已回退）':''}</span>`;}
function previewFlowCalls(steps,executionPolicy,stack=[]){const calls=[];for(const step of steps||[]){if(step.kind!=='flowCall')continue;const flow=state.flows.find(item=>item.id===step.flowId);if(!flow){calls.push(`<div class="execution-flow-preview missing">公共流程已删除 · ${esc(step.flowId||'')}</div>`);continue;}if(stack.includes(flow.id)){calls.push(`<div class="execution-flow-preview missing">${esc(flow.name)} · 循环调用</div>`);continue;}const selector=step.versionPolicy==='latest'?{policy:'latest'}:step.versionPolicy==='stable'?{policy:'stable'}:{policy:'specific',version:Number(step.flowVersion||flow.currentVersion||flow.version||1)};const resolved=executionSnapshot(flow,selector);calls.push(`<div class="execution-flow-preview"><span>↳ 公共流程 · ${esc(flow.name)} <b>v${resolved.version}</b></span>${previewModeHtml(resolved.snapshot,'steps',executionPolicy)}</div>`);calls.push(...previewFlowCalls(resolved.snapshot.steps,executionPolicy,[...stack,flow.id]));}return calls;}
function previewStageHtml(label,version,snapshot,phase,executionPolicy){const flows=previewFlowCalls(snapshot?.[phase]||[],executionPolicy);return `<div class="execution-stage-preview"><div><strong>${esc(label)}</strong><small>v${version}</small></div>${previewModeHtml(snapshot,phase,executionPolicy)}</div>${flows.join('')}`;}
function executionPolicyPreview(policy,executionPolicy='default'){const selections=buildExecutionSelections(policy);return `<div class="execution-confirm-list">${selections.map(selection=>{const suite=state.suites.find(item=>item.id===selection.suiteId);if(!suite)return'';const resolvedSuite=executionSnapshot(suite,selection.versionSelector||{policy}),suiteVersion=resolvedSuite.version,suiteSnapshot=resolvedSuite.snapshot;const selectedIds=selection.allCases?suiteSnapshotCaseIds(suiteSnapshot):selection.caseSelections.map(item=>item.caseId);const caseSelectors=new Map((selection.caseSelections||[]).map(item=>[item.caseId,item.versionSelector]));const cases=selectedIds.map(id=>state.cases.find(item=>item.id===id)).filter(Boolean);const compatibility=selection.membershipFallback?`<div class="notice membership-fallback"><strong>已自动匹配 Suite 成员版本：</strong>${policy==='stable'?'Stable':'Latest'} Suite v${selection.membershipFallback.requestedVersion} 不包含全部已选 Case；本次 Suite Setup/Teardown 改用包含这些 Case 的 v${selection.membershipFallback.resolvedVersion}。Case 版本仍按 ${policy==='stable'?'Stable':'Latest'} 执行。</div>`:selection.membershipError?`<div class="notice danger-notice membership-error"><strong>没有可执行的 Suite 版本：</strong>现有版本都不包含全部已选 Case。请先在 Suite 中保存成员关系后再执行。</div>`:'';return `<section><div class="split"><strong>${esc(suite.name)}</strong><span class="badge code">Suite v${suiteVersion}</span></div>${compatibility}<p>本次实际执行顺序（同一浏览器会话）</p><div class="execution-stage-list">${previewStageHtml('Suite Setup',suiteVersion,suiteSnapshot,'setupSteps',executionPolicy)}${cases.map(testCase=>{const resolvedCase=executionSnapshot(testCase,caseSelectors.get(testCase.id)||selection.caseVersionSelector||{policy});return `<div class="execution-case-preview"><div class="execution-case-heading"><strong>${esc(testCase.name)}</strong><span class="badge">Case v${resolvedCase.version}</span></div>${previewStageHtml('Case Setup',resolvedCase.version,resolvedCase.snapshot,'setupSteps',executionPolicy)}${previewStageHtml('测试步骤',resolvedCase.version,resolvedCase.snapshot,'steps',executionPolicy)}${previewStageHtml('Case Teardown',resolvedCase.version,resolvedCase.snapshot,'teardownSteps',executionPolicy)}</div>`;}).join('')||'<p class="muted">该 Suite 版本没有 Test Case</p>'}${previewStageHtml('Suite Teardown',suiteVersion,suiteSnapshot,'teardownSteps',executionPolicy)}</div></section>`;}).join('')}</div>`;}
async function executeSelectedItems(policy,node){let completed=false;const suiteSelections=buildExecutionSelections(policy),executionPolicy=$('#batchExecutionPolicy',node).value;if(suiteSelections.some(item=>item.membershipError))return toast('没有 Suite 版本包含全部已选 Case，请先保存 Suite 成员版本','error');const button=$('#confirmExecutionPolicy',node);button.disabled=true;button.textContent='执行中…';try{const run=await api('/api/executions/run',{method:'POST',body:JSON.stringify({suiteSelections,headless:false,versionSelector:{policy},caseVersionSelector:{policy},executionPolicy})});node.remove();$('#selectionRunResult').innerHTML=selectionRunHtml(run);toast('自定义执行完成');completed=true;}catch(error){completed=error.payload?.scope==='batch';node.remove();$('#selectionRunResult').innerHTML=completed?selectionRunHtml(error.payload):`<div class="run-summary failure">${esc(error.message)}</div>`;toast(error.message,'error');}finally{if(completed){executionTab='history';await refresh();}else await refresh(true);}}
function openExecutionPolicyDialog(){if(!buildExecutionSelections('stable').length)return toast('请至少选择一个测试计划、测试套件或测试用例','error');let policy='stable';const node=modal(`<h2>选择本次执行版本与方式</h2><p class="muted">本次选择会统一应用到所有已选 Test Suite 和 Test Case。执行记录会冻结实际版本与每个阶段的执行方式。</p><div class="execution-policy-grid"><button type="button" class="execution-policy selected" data-execution-policy="stable"><strong>Stable 稳定版本</strong><span>推荐用于回归和发布验证</span></button><button type="button" class="execution-policy" data-execution-policy="latest"><strong>Latest 最新版本</strong><span>用于验证刚录制或刚修改的内容</span></button></div><div class="field"><label>阶段执行方式</label><select id="batchExecutionPolicy"><option value="default">使用各阶段默认方式（推荐）</option><option value="prefer-native">优先按原生代码回放</option><option value="visual">全部按当前无代码步骤回放</option></select><small>每个 Suite 仍独占一套连续浏览器会话、一段录像和一个 Trace。</small></div><div class="notice"><strong>仍会执行完整生命周期：</strong>只选择 Case 时，也会执行所选策略对应的 Suite Setup 和 Suite Teardown。</div><div id="executionPolicyPreview"></div><div class="actions execution-confirm-actions"><button class="btn primary" id="confirmExecutionPolicy">使用 Stable 开始执行</button><button class="btn secondary" data-close>取消</button></div>`,true);const renderPreview=()=>{const selections=buildExecutionSelections(policy),blocked=selections.some(item=>item.membershipError),button=$('#confirmExecutionPolicy',node);$('#executionPolicyPreview',node).innerHTML=executionPolicyPreview(policy,$('#batchExecutionPolicy',node).value);button.disabled=blocked;button.textContent=blocked?'请先修复 Suite 成员版本':`使用 ${policy==='stable'?'Stable':'Latest'} 开始执行`;};$$('[data-execution-policy]',node).forEach(button=>button.onclick=()=>{policy=button.dataset.executionPolicy;$$('[data-execution-policy]',node).forEach(item=>item.classList.toggle('selected',item===button));renderPreview();});$('#batchExecutionPolicy',node).onchange=renderPreview;$('[data-close]',node).onclick=()=>node.remove();$('#confirmExecutionPolicy',node).onclick=()=>executeSelectedItems(policy,node);renderPreview();}
