  const filter=()=>{$$('#execCases .execution-case-row').forEach(row=>{const testCase=state.cases.find(item=>item.id===$('input',row).dataset.execCase);row.classList.toggle('hidden',Boolean($('#execPriority').value&&testCase.priority!==$('#execPriority').value)||Boolean($('#execTag').value&&!(testCase.tags||[]).some(tag=>tag.toLowerCase().includes($('#execTag').value.toLowerCase()))));});};$('#execPriority').onchange=filter;$('#execTag').oninput=filter;if($('#execSuiteVersion'))$('#execSuiteVersion').onchange=event=>{executionSelection.suiteVersions.set(activeSuite.id,parseExecutionVersion(event.target.value));render();};$$('[data-exec-case-version]').forEach(select=>select.onchange=()=>{executionSelection.caseVersions.set(select.dataset.execCaseVersion,parseExecutionVersion(select.value));render();});
  $('#startSelectionRun').onclick=openExecutionPolicyDialog;
