async function saveSettings(testCase){ let data;try{data=JSON.parse($('#data').value||'{}');}catch{return toast('测试数据不是有效 JSON','error');} await updateCase(testCase,{accountRef:$('#accountRef').value.trim(),data,configOverrides:['browser','locale','baseUrl','session','stability','proxy'],defaults:{...testCase.defaults,browser:$('#browser').value,locale:$('#locale').value.trim()||'zh-CN',baseUrl:$('#baseUrl').value.trim(),session:{...testCase.defaults.session,mode:$('#sessionMode').value},stability:{preset:$('#stabilityPreset').value,navigationTimeoutMs:Number($('#navigationTimeout').value||30000),actionTimeoutMs:Number($('#actionTimeout').value||10000),assertionTimeoutMs:Number($('#assertionTimeout').value||10000)},proxy:{...testCase.defaults.proxy,mode:$('#proxy').value.trim()?'proxy':'direct',server:$('#proxy').value.trim(),bypass:$('#proxyBypass').value.trim(),mappings:collectMappings()}}},'稳定性、会话隔离、配置、测试数据和代理映射已保存'); }
