const guideGroupLabels={all:'全部',navigation:'导航',action:'点击/滚动',form:'表单',wait:'等待/接口',dialog:'弹窗',window:'窗口',file:'文件',frame:'iframe',component:'复杂组件',assertion:'断言',locator:'定位',data:'数据',import:'导入兼容性'};
function openStepGuide(){let group='all';const node=modal(`<div class="guide-header"><div><h2>Playwright 步骤、断言与定位指南</h2><p class="muted">适用于 Suite Setup/Teardown、公共流程、Case Setup/测试步骤/Teardown。共 ${stepGuideCatalog.length} 条，可搜索操作名、使用场景或示例。</p></div><button class="btn primary" data-close>知道了</button></div><div class="guide-important"><strong>弹窗怎么确认？</strong><span>不要先写普通 click。直接选择“触发并接受弹窗”，定位触发弹窗的按钮；如果要点取消则选择“触发并拒绝弹窗”。之后可添加“弹窗消息”断言。</span></div><div class="guide-toolbar"><input id="guideSearch" placeholder="搜索：弹窗、iframe、上传、等待、URL、文本断言……"><div class="guide-filters">${Object.entries(guideGroupLabels).map(([key,label])=>`<button type="button" class="guide-filter ${key==='all'?'active':''}" data-guide-group="${key}">${label}</button>`).join('')}</div></div><div id="guideResults" class="guide-results"></div><div class="guide-links"><a href="https://playwright.dev/docs/input" target="_blank" rel="noreferrer">输入操作 ↗</a><a href="https://playwright.dev/docs/dialogs" target="_blank" rel="noreferrer">弹窗 ↗</a><a href="https://playwright.dev/docs/frames" target="_blank" rel="noreferrer">iframe ↗</a><a href="https://playwright.dev/docs/test-assertions" target="_blank" rel="noreferrer">断言 ↗</a><a href="https://playwright.dev/docs/locators" target="_blank" rel="noreferrer">定位器 ↗</a></div>`,true);const renderGuide=()=>{const query=$('#guideSearch',node).value.trim().toLowerCase();const rows=stepGuideCatalog.filter(item=>(group==='all'||item[0]===group)&&(!query||item.slice(1).join(' ').toLowerCase().includes(query)));$('#guideResults',node).innerHTML=rows.map(item=>`<article class="guide-item"><div class="guide-item-title"><span class="badge visual">${esc(guideGroupLabels[item[0]]||item[0])}</span><strong>${esc(item[1])}</strong></div><p>${esc(item[2])}</p><dl><div><dt>如何填写</dt><dd>${esc(item[3])}</dd></div><div><dt>示例 / 注意</dt><dd><code>${esc(item[4])}</code></dd></div></dl></article>`).join('')||'<div class="empty"><h3>没有匹配内容</h3><p>换一个关键词，例如“弹窗”“上传”或“文本”。</p></div>';};$('[data-close]',node).onclick=()=>node.remove();$('#guideSearch',node).oninput=renderGuide;$$('[data-guide-group]',node).forEach(button=>button.onclick=()=>{group=button.dataset.guideGroup;$$('[data-guide-group]',node).forEach(item=>item.classList.toggle('active',item===button));renderGuide();});renderGuide();}
function openDataGuide(){const node=modal(`<h2>测试账号与测试数据使用指南</h2><div class="data-example"><h3>1. 在“测试数据 JSON”填写</h3><pre>{
  "searchText": "playwright AI agent",
  "account": { "username": "qa-user" },
  "expected": { "title": "Search results" }
}</pre><h3>2. 无代码步骤</h3><p>fill 的“名称 / 输入 / 期望值”填写 <code>\${data.account.username}</code>；搜索词填写 <code>\${data.searchText}</code>；断言期望填写 <code>\${data.expected.title}</code>。</p><h3>3. JavaScript / Python</h3><pre>// JavaScript
await page.getByLabel('Username').fill(runtimeData.account.username);

# Python
await page.get_by_label('Username').fill(runtime_data['account']['username'])</pre><h3>4. 密码和敏感值</h3><p>不要放进 JSON 或源码。无代码步骤写 <code>\${env.COUPAY_PASSWORD}</code>；启动前在终端设置环境变量。测试账号字段只用于执行记录标识，不会自动填写账号。</p></div><div class="actions"><button class="btn primary" data-close>知道了</button></div>`,true);$('[data-close]',node).onclick=()=>node.remove();}
function currentLocatorDefaults(){const testCase=state.cases.find(item=>item.id===selectedCaseId);if(testCase)return testCase.defaults;const flow=state.flows.find(item=>item.id===selectedFlowId);if(flow)return flow.defaults;const suite=state.suites.find(item=>item.id===selectedSuiteId);return suite?.caseIds.map(id=>state.cases.find(item=>item.id===id)).find(Boolean)?.defaults||{browser:'chromium',locale:'zh-CN',proxy:{mode:'direct'},stability:{navigationTimeoutMs:30000}};}
function openLocatorFinder(row){const defaults=currentLocatorDefaults();const node=modal(`<h2>推荐 Playwright 定位器 / XPath</h2><p class="muted">实现方式：服务器使用当前用例的浏览器、语言和代理打开已授权 URL，只读取可见交互元素的 DOM 与可访问属性；按 testId、role、label、id、name、text、class、CSS、XPath 的稳定性打分。不会自动保存，选择后还需要回放验证。</p><div class="field-grid"><div class="field full"><label>页面 URL</label><input id="finderUrl" value="${esc(defaults.baseUrl||'')}" placeholder="https://qa.example.com/page"></div><div class="field full"><label>元素提示（页面上的文字、名称或 ID）</label><input id="finderHint" value="${esc($('.locatorName',row)?.value||$('.locator',row)?.value||'')}" placeholder="例如 搜索、登录、Email"></div></div><div class="actions" style="margin-top:14px"><button class="btn primary" id="runFinder">扫描并生成候选</button><button class="btn secondary" data-close>取消</button></div><div id="finderResults"></div>`,true);$('[data-close]',node).onclick=()=>node.remove();$('#runFinder',node).onclick=async()=>{const button=$('#runFinder',node);button.disabled=true;$('#finderResults',node).innerHTML='<p class="muted">正在打开页面并分析可见元素…</p>';try{const result=await api('/api/locator-suggestions',{method:'POST',body:JSON.stringify({url:$('#finderUrl',node).value.trim(),hint:$('#finderHint',node).value.trim(),defaults})});$('#finderResults',node).innerHTML=`<div class="notice">${esc(result.warning)}</div><p class="muted">点击候选会回填本步骤；分数越高通常越稳定。XPath/CSS 排在最后。</p><div class="locator-suggestions">${result.suggestions.map(item=>`<button class="locator-suggestion" data-strategy="${esc(item.strategy)}" data-value="${esc(item.value)}" data-name="${esc(item.name||'')}" data-operator="${esc(item.operator)}"><strong>${item.score} 分 · ${esc(item.strategy)} · ${esc(item.preview)}</strong><span>${esc(item.reason)}</span></button>`).join('')||'<p class="muted">没有找到匹配元素，请换一个提示词或确认页面已加载。</p>'}</div>`;$$('.locator-suggestion',node).forEach(item=>item.onclick=()=>{$('.strategy',row).value=item.dataset.strategy;$('.locator',row).value=item.dataset.value;$('.locatorOperator',row).value=item.dataset.operator;if(item.dataset.strategy==='role')$('.locatorName',row).value=item.dataset.name;updateStepControls(row);node.remove();markStepsChanged(`已应用 ${item.dataset.strategy} 定位器`);});}catch(error){$('#finderResults',node).innerHTML=`<div class="notice danger-text">${esc(error.message)}</div>`;}finally{button.disabled=false;}};}
async function openAiDiagnosis(runId){const node=modal(`<h2>本地 AI 失败诊断</h2><p class="muted">正在读取失败步骤、网络异常和诊断证据。AI 不能修改代理密码，也不会绕过站点安全控制。</p><div id="aiBody">分析中…</div><div class="actions"><button class="btn secondary" data-close>关闭</button></div>`,true);$('[data-close]',node).onclick=()=>node.remove();try{const result=await api(`/api/runs/${runId}/ai-diagnose`,{method:'POST',body:'{}'});$('#aiBody',node).innerHTML=`<div class="notice"><strong>${esc(result.provider)}</strong><br>${esc(result.summary)}${result.localAiWarning?`<br>${esc(result.localAiWarning)}`:''}</div><div class="list">${result.suggestions.map(item=>`<article class="ai-suggestion"><div><strong>${esc(item.title)}</strong><p>${esc(item.reason)}</p><small>置信度 ${Math.round(item.confidence*100)}%</small></div>${item.patch?`<button class="btn primary apply-ai-fix" data-id="${item.id}">预览并 Apply</button>`:'<span class="badge">需人工处理</span>'}</article>`).join('')}</div><p class="muted">${esc(result.disclaimer)}</p>`;$$('.apply-ai-fix',node).forEach(button=>button.onclick=async()=>{const suggestion=result.suggestions.find(item=>item.id===button.dataset.id);if(!confirm(`将应用：${suggestion.title}\n\n${suggestion.reason}\n\n是否继续？`))return;button.disabled=true;try{await api(`/api/runs/${runId}/apply-fix`,{method:'POST',body:JSON.stringify({suggestionId:suggestion.id})});node.remove();toast('建议已应用到失败步骤，JS/Python 已同步；请重新回放验证');await refresh();}catch(error){button.disabled=false;toast(error.message,'error');}});}catch(error){$('#aiBody',node).innerHTML=`<div class="notice danger-text">${esc(error.message)}</div>`;}}
function openSuiteModal(suite,planId){const selectedParent=suite?.planId||planId||state.plans[0]?.id||'';const node=modal(`<h2>${suite?'编辑':'新建'}测试套件</h2><p class="muted">严格层级：每个测试套件必须属于一个测试计划。运行完整 Suite 时，Setup、公共流程、全部 Case 和 Teardown 共享同一浏览器会话与录像。</p><div class="field-grid"><div class="field full"><label>所属测试计划 *</label><select id="mSuitePlan"><option value="">请选择测试计划</option>${state.plans.map(plan=>`<option value="${plan.id}" ${plan.id===selectedParent?'selected':''}>${esc(plan.name)}</option>`).join('')}</select></div><div class="field full"><label>套件名称</label><input id="mSuiteName" value="${esc(suite?.name||'')}"></div><div class="field full"><label>套件说明</label><textarea id="mSuiteDesc">${esc(suite?.description||'')}</textarea></div><div class="notice full"><strong>执行会话：</strong>运行整个 Suite 时固定使用单一 Browser / Context / Page 会话、单一 Trace 和主录像；单独回放某个阶段、Case 或公共流程时才创建独立会话。</div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="mSuiteSave">保存</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#mSuiteSave',node).onclick=async()=>{try{const parentId=$('#mSuitePlan',node).value;if(!parentId)throw new Error('请选择所属测试计划');const body={planId:parentId,name:$('#mSuiteName',node).value.trim()||'新测试套件',description:$('#mSuiteDesc',node).value.trim(),sessionPolicy:'shared-current-run',...(suite?{caseIds:suite.caseIds,setupSteps:suite.setupSteps,teardownSteps:suite.teardownSteps,...versionSavePatch('suite',suite.id)}:{})};const saved=await api(suite?`/api/suites/${suite.id}`:'/api/suites',{method:suite?'PUT':'POST',body:JSON.stringify(body)});if(suite)finishVersionEdit('suite',suite.id);node.remove();selectedSuiteId=saved.id;view='suites';toast('测试套件已保存');await refresh();}catch(error){toast(error.message,'error');}};}
function openAddSuite(plan){const candidates=state.suites.filter(s=>!(plan.suiteIds||[]).includes(s.id));const node=modal(`<h2>加入已有测试套件</h2><div class="list">${candidates.map(suiteRowHtml).join('')||emptyHtml('没有可加入的套件','请先新建测试套件。')}</div><div class="actions" style="margin-top:16px"><button class="btn secondary" data-close>关闭</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$$('[data-suite]',node).forEach(item=>item.onclick=async()=>{await api(`/api/plans/${plan.id}/suites/${item.dataset.suite}`,{method:'POST'});node.remove();toast('套件已加入计划');await refresh();});}
function openAddCaseToSuite(suite){const candidates=state.cases.filter(c=>!suite.caseIds.includes(c.id));const node=modal(`<h2>加入已有测试用例</h2><div class="list">${candidates.map(caseRowHtml).join('')||emptyHtml('没有可加入的用例','请先新建一个测试用例。')}</div><div class="actions" style="margin-top:16px"><button class="btn secondary" data-close>关闭</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$$('[data-case]',node).forEach(item=>item.onclick=async()=>{await api(`/api/suites/${suite.id}/cases/${item.dataset.case}`,{method:'POST'});node.remove();toast('用例已加入套件');await refresh();});}
async function saveSuiteLifecycle(suite){try{await api(`/api/suites/${suite.id}`,{method:'PUT',body:JSON.stringify({...suite,...versionSavePatch('suite',suite.id),[suitePhase]:collectSteps({steps:suite[suitePhase]})})});finishVersionEdit('suite',suite.id);toast('Suite 生命周期已保存');await refresh();}catch(error){toast(error.message,'error');}}
function openStructuredRecordDialog(type,owner){const isSuite=type==='suite';const title=isSuite?(suitePhase==='setupSteps'?'Suite Setup':'Suite Teardown'):'公共流程';let selected='standard';const node=modal(`<h2>录制 ${title}</h2><p class="muted">关闭 Inspector 后自动导入 JavaScript、Python 和无代码步骤。已有步骤不会直接覆盖，平台会再次请求确认。</p><div class="record-mode-grid"><button class="record-mode selected" data-mode="standard"><strong>标准录制</strong><span>直接录制 ${title}</span></button><button class="record-mode" data-mode="manual"><strong>手工登录后录制</strong><span>登录并标记边界后，只保存后续步骤</span></button></div><div id="structuredManual" class="record-compliance hidden"><p><strong>两阶段流程：</strong>先完成登录并点击“登录完成，开始录制业务步骤”，然后录制要保存到 ${title} 的操作。</p></div>${!isSuite?`<div class="notice">录制使用公共流程保存的页面语言和代理。如果目标站不能直连，请先在“编辑信息”中配置代理。</div>`:''}<div class="field-grid"><div class="field full"><label>起始 URL（可选）</label><input id="structuredUrl" placeholder="https://qa.example.com"></div><div class="field full"><label>浏览器</label><select id="structuredBrowser"><option value="chromium">Chrome / Chromium</option><option value="firefox">Firefox</option><option value="webkit">WebKit</option></select></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="startStructuredRecord">打开录制浏览器</button><button class="btn secondary" data-close>取消</button></div>`);if(owner.defaults?.browser)$('#structuredBrowser',node).value=owner.defaults.browser;$('[data-close]',node).onclick=()=>node.remove();$$('[data-mode]',node).forEach(button=>button.onclick=()=>{selected=button.dataset.mode;$$('[data-mode]',node).forEach(item=>item.classList.toggle('selected',item===button));$('#structuredManual',node).classList.toggle('hidden',selected!=='manual');});$('#startStructuredRecord',node).onclick=async()=>{const button=$('#startStructuredRecord',node);button.disabled=true;try{const phase=suitePhase==='setupSteps'?'setup':'teardown';const path=isSuite?`/api/suites/${owner.id}/phases/${phase}/record`:`/api/flows/${owner.id}/record`;const session=await api(path,{method:'POST',body:JSON.stringify({url:$('#structuredUrl',node).value.trim(),browser:$('#structuredBrowser',node).value,manualLogin:selected==='manual'})});node.remove();const selector=isSuite?'#suitePhaseResult':'#flowRunResult';showRecordingStatus(session,false,selector);pollTargetRecording({type,selector},session.id);}catch(error){button.disabled=false;toast(error.message,'error');}};}
async function runSuitePhase(suite){return chooseVersion('suite',suite,(selector,executionPolicy)=>executeSuitePhaseVersion(suite,selector,executionPolicy),{phase:suitePhase});}
async function executeSuitePhaseVersion(suite,versionSelector,executionPolicy='default'){const phase=suitePhase==='setupSteps'?'setup':'teardown';const button=$('#runSuitePhase');if(button){button.disabled=true;button.textContent='回放中…';}try{const run=await api(`/api/suites/${suite.id}/phases/${phase}/run`,{method:'POST',body:JSON.stringify({headless:false,versionSelector,executionPolicy})});$('#suitePhaseResult').innerHTML=runResultHtml(run);toast(`${phase==='setup'?'Suite Setup':'Suite Teardown'} v${run.resolvedVersion} 回放通过`);}catch(error){$('#suitePhaseResult').innerHTML=error.payload?.status?runResultHtml(error.payload):`<div class="run-summary failure">${esc(error.message)}</div>`;toast('Suite 阶段回放失败','error');}finally{if(button){button.disabled=false;button.textContent='回放此阶段';}await refresh(true);}}
async function runSuite(suite,initialSelector={policy:'stable'}){const node=modal(`<h2>配置 Test Suite 回放版本与方式</h2><p class="muted">所有阶段仍在同一个浏览器会话、一段录像和一个 Trace 中执行。</p><div class="field"><label>Suite 版本</label><select id="suiteReplayVersion">${executionVersionOptions(suite,initialSelector)}</select></div><div class="field"><label>执行方式</label><select id="suiteExecutionPolicy"><option value="default">使用各阶段默认方式（推荐）</option><option value="prefer-native">优先按原生代码回放</option><option value="visual">全部按当前无代码步骤回放</option></select><small>缺少原生回放代码的阶段会明确回退到当前步骤，不会创建新浏览器。</small></div><div id="suiteReplayPreview"></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="confirmSuiteReplay">开始回放</button><button class="btn secondary" data-close>取消</button></div>`,true);const updateDetails=()=>{const suiteSelector=parseExecutionVersion($('#suiteReplayVersion',node).value),resolvedSuite=executionSnapshot(suite,suiteSelector),policy=$('#suiteExecutionPolicy',node).value,caseSelections=$$('[data-suite-replay-case]',node).map(select=>({testCase:state.cases.find(item=>item.id===select.dataset.suiteReplayCase),selector:parseExecutionVersion(select.value)})).filter(item=>item.testCase);$('#suiteReplayStages',node).innerHTML=`<h3>本次实际执行来源</h3><div class="execution-stage-list">${previewStageHtml('Suite Setup',resolvedSuite.version,resolvedSuite.snapshot,'setupSteps',policy)}${caseSelections.map(item=>{const resolvedCase=executionSnapshot(item.testCase,item.selector);return `<div class="execution-case-preview"><div class="execution-case-heading"><strong>${esc(item.testCase.name)}</strong><span class="badge">Case v${resolvedCase.version}</span></div>${previewStageHtml('Case Setup',resolvedCase.version,resolvedCase.snapshot,'setupSteps',policy)}${previewStageHtml('测试步骤',resolvedCase.version,resolvedCase.snapshot,'steps',policy)}${previewStageHtml('Case Teardown',resolvedCase.version,resolvedCase.snapshot,'teardownSteps',policy)}</div>`;}).join('')}${previewStageHtml('Suite Teardown',resolvedSuite.version,resolvedSuite.snapshot,'teardownSteps',policy)}</div>`;};const renderPreview=()=>{const selector=parseExecutionVersion($('#suiteReplayVersion',node).value),version=resolvedExecutionVersion(suite,selector),snapshot=(suite.versions||[]).find(item=>Number(item.version)===version)?.snapshot||suite,bindings=snapshot.caseBindings||[],policy=$('#suiteExecutionPolicy',node).value;$('#suiteReplayPreview',node).innerHTML=`<div class="notice"><strong>单会话执行：</strong>Suite Setup → 公共流程 → Case Setup/测试步骤/Teardown → Suite Teardown。当前策略：${policy==='default'?'各阶段默认':policy==='prefer-native'?'优先原生代码':'全部当前步骤'}。</div><div class="execution-version-lifecycle"><div><small>Suite Setup</small><strong>v${version}</strong></div><b>→</b><div><small>Test Case</small><strong>${bindings.length} 个</strong></div><b>→</b><div><small>Suite Teardown</small><strong>v${version}</strong></div></div><div class="execution-case-versions">${bindings.map(binding=>{const testCase=state.cases.find(item=>item.id===binding.caseId);if(!testCase)return'';const selected={policy:binding.versionPolicy==='pinned'?'specific':binding.versionPolicy||'latest',...(binding.version?{version:binding.version}:{})};return `<div class="execution-case-version"><div><strong>${esc(testCase.name)}</strong><small>Suite v${version} 保存策略：${esc(binding.versionPolicy||'latest')}</small></div><select data-suite-replay-case="${testCase.id}">${executionVersionOptions(testCase,selected)}</select></div>`;}).join('')||'<p class="muted">该 Suite 版本没有 Test Case。</p>'}</div><div id="suiteReplayStages"></div>`;$$('[data-suite-replay-case]',node).forEach(select=>select.onchange=updateDetails);updateDetails();};$('#suiteReplayVersion',node).onchange=renderPreview;$('#suiteExecutionPolicy',node).onchange=updateDetails;renderPreview();$('[data-close]',node).onclick=()=>node.remove();$('#confirmSuiteReplay',node).onclick=()=>{const versionSelector=parseExecutionVersion($('#suiteReplayVersion',node).value),caseSelections=$$('[data-suite-replay-case]',node).map(select=>({caseId:select.dataset.suiteReplayCase,versionSelector:parseExecutionVersion(select.value)})),executionPolicy=$('#suiteExecutionPolicy',node).value;node.remove();executeSuiteVersion(suite,versionSelector,caseSelections,executionPolicy);};}
async function executeSuiteVersion(suite,versionSelector,caseSelections,executionPolicy='default'){const button=$('#runSuite');if(button){button.disabled=true;button.textContent='套件执行中…';}try{const run=await api(`/api/suites/${suite.id}/run`,{method:'POST',body:JSON.stringify({headless:false,versionSelector,executionPolicy,...(caseSelections?{caseSelections}:{})})});$('#suiteRunResult').innerHTML=suiteRunResultHtml(run);toast(`测试套件 v${run.resolvedVersion} 执行完成`);}catch(error){$('#suiteRunResult').innerHTML=error.payload?.scope==='suite'?suiteRunResultHtml(error.payload):`<div class="run-summary failure">${esc(error.message)}</div>`;toast('测试套件执行失败','error');}finally{if(button){button.disabled=false;button.textContent='运行套件';}await refresh(true);bindRunRows();}}
function suiteRunResultHtml(run){const cases=(run.resolvedDependencies||[]).filter(item=>item.type==='case'),flows=(run.resolvedDependencies||[]).filter(item=>item.type==='flow');return `<div class="run-summary ${run.status==='passed'?'success':'failure'}"><div class="split"><strong>${run.status==='passed'?'套件全部通过':'套件执行失败'}</strong>${statusBadge(run.status)}</div><p>Suite v${run.resolvedVersion||'?'} · Setup ${run.setupRun?.status||'未配置'} · Case ${run.summary?.passed||0} 通过/${run.summary?.failed||0} 失败/${run.summary?.skipped||0} 跳过 · Teardown ${run.teardownRun?.status||'未配置'}</p>${cases.length?`<p class="muted">实际用例版本：${cases.map(item=>`${esc(item.name)} v${item.resolvedVersion}`).join('、')}</p>`:''}${flows.length?`<p class="muted">实际公共流程版本：${flows.map(item=>`${esc(item.name)} v${item.resolvedVersion}`).join('、')}</p>`:''}</div>${hierarchicalRunHtml(run,run.id)}`;}
async function deleteSuite(suite){if(!confirm(`删除测试套件“${suite.name}”？其中测试用例不会删除。`))return;await api(`/api/suites/${suite.id}`,{method:'DELETE'});selectedSuiteId=undefined;toast('测试套件已删除');await refresh();}
function openFlowModal(flow){const defaults=flow?.defaults||{browser:'chromium',locale:'zh-CN',proxy:{mode:'direct',server:'',bypass:''},stability:{navigationTimeoutMs:30000,actionTimeoutMs:10000,assertionTimeoutMs:10000}};const ownerOptions=type=>type==='suite'?state.suites.map(suite=>`<option value="${suite.id}" ${suite.id===flow?.suiteId?'selected':''}>${esc(state.plans.find(plan=>plan.id===suite.planId)?.name||'未归档')} → ${esc(suite.name)}</option>`).join(''):state.cases.map(testCase=>`<option value="${testCase.id}" ${testCase.id===flow?.caseId?'selected':''}>${esc(state.suites.find(suite=>suite.id===testCase.suiteId)?.name||'未归档')} → ${esc(testCase.name)}</option>`).join('');const node=modal(`<h2>${flow?'编辑':'新建'}公共流程</h2><div class="field-grid"><div class="field full"><label>流程名称</label><input id="mFlowName" value="${esc(flow?.name||'')}"></div><div class="field full"><label>流程说明</label><textarea id="mFlowDesc">${esc(flow?.description||'')}</textarea></div><div class="field"><label>流程归属</label><select id="mFlowOwnerType"><option value="global">全局公共流程</option><option value="suite">属于 Test Suite</option><option value="case">属于 Test Case</option></select></div><div class="field"><label>所属资产</label><select id="mFlowOwner"></select></div><div class="field full"><small>Suite 流程用于该 Suite 生命周期与子用例；Case 流程只用于当前用例；全局流程可跨层级复用。</small></div><div class="field full"><label>安全级别</label><select id="mFlowSafety"><option value="normal">普通流程</option><option value="destructive">敏感操作：支付/绑卡/下单（禁止自动重试）</option></select></div><div class="field full"><h3>独立录制/回放配置</h3><small>当公共流程被 Case 或 Suite 引用时，使用调用方当前共享会话和执行配置。</small></div><div class="field"><label>浏览器</label><select id="mFlowBrowser"><option value="chromium">Chrome / Chromium</option><option value="firefox">Firefox</option><option value="webkit">WebKit</option></select></div><div class="field"><label>页面语言</label><input id="mFlowLocale" value="${esc(defaults.locale||'zh-CN')}" placeholder="zh-CN / en-US / ko-KR"></div><div class="field"><label>连接方式</label><select id="mFlowProxyMode"><option value="direct">直接连接</option><option value="proxy">使用代理</option></select></div><div class="field"><label>代理服务器</label><input id="mFlowProxyServer" value="${esc(defaults.proxy?.server||'')}" placeholder="http://127.0.0.1:7897"></div><div class="field full"><label>代理绕过列表</label><input id="mFlowProxyBypass" value="${esc(defaults.proxy?.bypass||'')}" placeholder="localhost,127.0.0.1"></div><div class="field"><label>导航超时 (ms)</label><input id="mFlowNavTimeout" type="number" min="1000" value="${Number(defaults.stability?.navigationTimeoutMs||30000)}"></div><div class="field"><label>操作/断言超时 (ms)</label><input id="mFlowActionTimeout" type="number" min="1000" value="${Number(defaults.stability?.actionTimeoutMs||10000)}"></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="mFlowSave">保存</button><button class="btn secondary" data-close>取消</button></div>`,true);const updateOwner=()=>{const type=$('#mFlowOwnerType',node).value;$('#mFlowOwner',node).innerHTML=type==='global'?'<option value="">不限定资产</option>':`<option value="">请选择所属${type==='suite'?'套件':'用例'}</option>${ownerOptions(type)}`;$('#mFlowOwner',node).disabled=type==='global';};$('#mFlowOwnerType',node).value=flow?.ownerType||'global';updateOwner();$('#mFlowOwnerType',node).onchange=updateOwner;$('#mFlowSafety',node).value=flow?.safety||'normal';$('#mFlowBrowser',node).value=defaults.browser||'chromium';$('#mFlowProxyMode',node).value=defaults.proxy?.mode||'direct';$('[data-close]',node).onclick=()=>node.remove();$('#mFlowSave',node).onclick=async()=>{try{const proxyMode=$('#mFlowProxyMode',node).value,proxyServer=$('#mFlowProxyServer',node).value.trim(),ownerType=$('#mFlowOwnerType',node).value,ownerId=$('#mFlowOwner',node).value;if(proxyMode==='proxy'&&!proxyServer)throw new Error('选择“使用代理”后必须填写代理服务器');if(ownerType!=='global'&&!ownerId)throw new Error('请选择公共流程所属资产');const body={ownerType,suiteId:ownerType==='suite'?ownerId:null,caseId:ownerType==='case'?ownerId:null,name:$('#mFlowName',node).value.trim()||'新公共流程',description:$('#mFlowDesc',node).value.trim(),safety:$('#mFlowSafety',node).value,defaults:{...defaults,browser:$('#mFlowBrowser',node).value,locale:$('#mFlowLocale',node).value.trim()||'zh-CN',proxy:{...(defaults.proxy||{}),mode:proxyMode,server:proxyServer,bypass:$('#mFlowProxyBypass',node).value.trim()},stability:{...(defaults.stability||{}),navigationTimeoutMs:Number($('#mFlowNavTimeout',node).value||30000),actionTimeoutMs:Number($('#mFlowActionTimeout',node).value||10000),assertionTimeoutMs:Number($('#mFlowActionTimeout',node).value||10000)}},...(flow?{steps:flow.steps,parameters:flow.parameters,...versionSavePatch('flow',flow.id)}:{steps:[],parameters:[]})};const saved=await api(flow?`/api/flows/${flow.id}`:'/api/flows',{method:flow?'PUT':'POST',body:JSON.stringify(body)});if(flow)finishVersionEdit('flow',flow.id);node.remove();selectedFlowId=saved.id;view='flows';toast('公共流程已保存');await refresh();}catch(error){toast(error.message,'error');}};}
async function saveFlowSteps(flow){try{let parameters=JSON.parse($('#flowParameters').value||'[]');if(!Array.isArray(parameters))throw new Error('参数必须是 JSON 数组');const saved=await api(`/api/flows/${flow.id}`,{method:'PUT',body:JSON.stringify({...flow,...versionSavePatch('flow',flow.id),parameters,steps:collectSteps({steps:flow.steps})})});finishVersionEdit('flow',flow.id);toast(`公共流程已保存为 v${saved.version}`);await refresh();}catch(error){toast(error.message,'error');}}
async function runFlow(flow){return chooseVersion('flow',flow,(selector,executionPolicy)=>executeFlowVersion(flow,selector,{},executionPolicy),{phase:'steps'});}
async function executeFlowVersion(flow,versionSelector,initialData={},executionPolicy='default'){const node=modal(`<h2>回放公共流程 v${versionSelector.version||versionSelector.policy}</h2><p class="muted">为流程参数填写本次测试数据，格式为 JSON 对象。</p><div class="field full"><label>测试数据 JSON</label><textarea id="flowRunData">${esc(JSON.stringify(initialData,null,2))}</textarea></div><div class="notice">执行方式：${executionPolicy==='prefer-native'?'按原生代码回放':'按当前步骤回放'}</div><div class="actions" style="margin-top:16px"><button class="btn primary" id="confirmRunFlow">开始回放</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#confirmRunFlow',node).onclick=async()=>{let data;try{data=JSON.parse($('#flowRunData',node).value||'{}');}catch{return toast('测试数据不是有效 JSON','error');}const button=$('#confirmRunFlow',node);button.disabled=true;try{const run=await api(`/api/flows/${flow.id}/run`,{method:'POST',body:JSON.stringify({headless:false,data,versionSelector,executionPolicy})});node.remove();$('#flowRunResult').innerHTML=runResultHtml(run);toast(`公共流程 v${run.resolvedVersion} 回放通过`);}catch(error){node.remove();$('#flowRunResult').innerHTML=error.payload?.status?runResultHtml(error.payload):`<div class="run-summary failure">${esc(error.message)}</div>`;toast('公共流程回放失败','error');}finally{await refresh(true);}};}
async function deleteFlow(flow){if(!confirm(`删除公共流程“${flow.name}”？`))return;try{await api(`/api/flows/${flow.id}`,{method:'DELETE'});selectedFlowId=undefined;toast('公共流程已删除');await refresh();}catch(error){toast(error.message,'error');}}
function openPlanModal(plan){const node=modal(`<h2>${plan?'编辑':'新建'}测试计划</h2><p class="muted">计划名称会用作本地测试文件夹名。</p><div class="field-grid"><div class="field full"><label>计划名称</label><input id="mName" value="${esc(plan?.name||'')}"></div><div class="field full"><label>计划说明</label><textarea id="mDesc">${esc(plan?.description||'')}</textarea></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="mSave">保存</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#mSave',node).onclick=async()=>{try{const saved=await api(plan?`/api/plans/${plan.id}`:'/api/plans',{method:plan?'PUT':'POST',body:JSON.stringify({name:$('#mName',node).value.trim()||'新测试计划',description:$('#mDesc',node).value.trim()})});node.remove();selectedPlanId=saved.id;view='plans';toast('测试计划已保存');await refresh();}catch(error){toast(error.message,'error');}};}
function openCaseModal(planId,suiteId){const available=state.suites.filter(suite=>!planId||suite.planId===planId);const selectedParent=suiteId||available[0]?.id||state.suites[0]?.id||'';const node=modal(`<h2>新建测试用例</h2><p class="muted">严格层级：测试用例必须属于一个 Test Suite，而不是直接属于 Test Plan。</p><div class="field-grid"><div class="field full"><label>所属测试套件 *</label><select id="mCaseSuite"><option value="">请选择测试套件</option>${state.suites.map(suite=>{const plan=state.plans.find(item=>item.id===suite.planId);return`<option value="${suite.id}" ${suite.id===selectedParent?'selected':''}>${esc(plan?.name||'未归档')} → ${esc(suite.name)}</option>`;}).join('')}</select></div><div class="field full"><label>用例名称</label><input id="mCaseName" placeholder="例如：有效账号登录"></div><div class="field"><label>编辑模式</label><select id="mMode"><option value="visual">无代码步骤（适合小白）</option><option value="code">Playwright 代码（适合开发者）</option></select></div><div class="field"><label>优先级</label><select id="mCasePriority"><option>P0</option><option selected>P1</option><option>P2</option></select></div><div class="field full"><label>标签（逗号分隔）</label><input id="mCaseTags" placeholder="CICD, stable, smoke"><small>可填写多个标签，使用逗号分隔。</small></div></div><div class="actions" style="margin-top:16px"><button class="btn primary" id="mCreate">创建用例</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#mCreate',node).onclick=async()=>{try{const parentId=$('#mCaseSuite',node).value;if(!parentId)throw new Error('请先创建并选择所属测试套件');const tags=$('#mCaseTags',node).value.split(',').map(item=>item.trim()).filter(Boolean);const testCase=await api('/api/cases',{method:'POST',body:JSON.stringify({suiteId:parentId,name:$('#mCaseName',node).value.trim()||'新测试用例',editorMode:$('#mMode',node).value,priority:$('#mCasePriority',node).value,tags})});node.remove();selectedCaseId=testCase.id;view='cases';caseTab=$('#mMode',node).value==='code'?'code':'visual';toast('测试用例已创建');await refresh();}catch(error){toast(error.message,'error');}};}
function openAddCase(plan){const candidates=state.cases.filter(c=>!plan.caseIds.includes(c.id));const node=modal(`<h2>加入已有测试用例</h2><p class="muted">加入后会把 JS 和 Python 文件保存到该计划文件夹。</p><div class="list">${candidates.map(caseRowHtml).join('')||emptyHtml('没有可加入的用例','请先新建一个测试用例。')}</div><div class="actions" style="margin-top:16px"><button class="btn secondary" data-close>关闭</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$$('[data-case]',node).forEach(item=>item.onclick=async()=>{await api(`/api/plans/${plan.id}/cases/${item.dataset.case}`,{method:'POST'});node.remove();toast('用例已加入计划并保存源码文件');await refresh();});}
async function deletePlan(plan){if(!confirm(`删除测试计划“${plan.name}”？计划内测试用例不会删除。`))return;await api(`/api/plans/${plan.id}`,{method:'DELETE'});selectedPlanId=undefined;toast('测试计划已删除');await refresh();}
async function deleteCase(testCase){if(!confirm(`删除测试用例“${testCase.name}”？执行记录和 artifact 会保留。`))return;await api(`/api/cases/${testCase.id}`,{method:'DELETE'});selectedCaseId=undefined;view='cases';toast('测试用例已删除');await refresh();}

function openDefaultExecutionModes(type,owner,version,parent){const entry=(owner.versions||[]).find(item=>Number(item.version)===Number(version));const phases=type==='case'?[['Case Setup','setupSteps'],['测试步骤','steps'],['Case Teardown','teardownSteps']]:type==='suite'?[['Suite Setup','setupSteps'],['Suite Teardown','teardownSteps']]:[['公共流程','steps']];const node=modal(`<h2>设置默认回放方式 · v${version}</h2><p class="muted">历史快照不会被修改；保存后会基于 v${version} 创建一个新版本。</p><div class="field-grid">${phases.map(([label,key])=>{const native=Boolean(entry?.nativePhases?.[key]);const selected=entry?.executionModes?.[key]==='native'&&native?'native':'visual';return `<div class="field"><label>${label}</label><select data-mode-phase="${key}"><option value="visual" ${selected==='visual'?'selected':''}>当前无代码步骤</option><option value="native" ${selected==='native'?'selected':''} ${native?'':'disabled'}>原生回放代码${native?'':'（该版本没有原生代码）'}</option></select></div>`;}).join('')}</div><div class="actions"><button class="btn primary" id="saveDefaultModes">保存为新版本</button><button class="btn secondary" data-close>取消</button></div>`);$('[data-close]',node).onclick=()=>node.remove();$('#saveDefaultModes',node).onclick=async()=>{const executionModes=Object.fromEntries($$('[data-mode-phase]',node).map(select=>[select.dataset.modePhase,select.value]));await api(`/api/${assetRoute(type)}/${owner.id}/versions/${version}/execution-modes`,{method:'POST',body:JSON.stringify({executionModes})});node.remove();parent?.remove();toast('默认回放方式已保存为新版本');await refresh();};}
async function saveNativeSource(button){const type=button.dataset.nativeType,id=button.dataset.nativeId,phase=button.dataset.nativePhase,version=Number(button.dataset.nativeVersion),container=button.closest('.native-source'),editor=$('.native-runnable-code',container),javascript=editor?.value||'';const collection=type==='case'?state.cases:type==='suite'?state.suites:state.flows,owner=collection.find(item=>item.id===id),current=owner?.recordedSources?.[phase]?.runnableJavascript||'';if(!javascript.trim())return toast('原生回放代码不能为空','error');if(javascript.trim()===current.trim())return toast('原生回放代码没有变更');button.disabled=true;button.textContent='保存中…';try{const saved=await api(`/api/${assetRoute(type)}/${id}/versions/${version}/native-source`,{method:'POST',body:JSON.stringify({phase,javascript})});toast(`原生回放代码已保存为 v${saved.currentVersion}，录制时原始快照未修改`);await refresh();}catch(error){button.disabled=false;button.textContent='保存原生代码并创建新版本';toast(error.message,'error');}}
function enhanceVersionManager(){if(!activeVersionManager)return;$$('.version-list .version-row').forEach(row=>{if($('.default-mode-version',row)||row.classList.contains('archived'))return;const anchor=$('.metadata-version',row);if(!anchor)return;const button=document.createElement('button');button.className='btn small secondary default-mode-version';button.textContent='默认回放方式';button.onclick=()=>openDefaultExecutionModes(activeVersionManager.type,activeVersionManager.owner,Number(anchor.dataset.version),row.closest('.modal'));anchor.after(button);});}
document.addEventListener('click',event=>{if(event.target.closest('#caseVersions'))activeVersionManager={type:'case',owner:state.cases.find(item=>item.id===selectedCaseId)};else if(event.target.closest('#suiteVersions'))activeVersionManager={type:'suite',owner:state.suites.find(item=>item.id===selectedSuiteId)};else if(event.target.closest('#flowVersions'))activeVersionManager={type:'flow',owner:state.flows.find(item=>item.id===selectedFlowId)};setTimeout(enhanceVersionManager);},true);
new MutationObserver(enhanceVersionManager).observe(document.body,{childList:true,subtree:true});

$$('.nav-link').forEach(node=>node.onclick=()=>go(node.dataset.view));
document.addEventListener('click',event=>{if(event.target.closest('#reclassifySteps')){event.preventDefault();openReclassifySteps();}});
document.addEventListener('click',event=>{const nativeSave=event.target.closest('.save-native-source');if(nativeSave){event.preventDefault();saveNativeSource(nativeSave);return;}const cancelVersion=event.target.closest('.cancel-version-edit');if(cancelVersion){event.preventDefault();versionEditContext=null;refresh();return;}const dataGuide=event.target.closest('.open-data-guide');if(dataGuide){event.preventDefault();openDataGuide();return;}const guide=event.target.closest('.open-step-guide');if(guide){event.preventDefault();openStepGuide();return;}const ai=event.target.closest('.ai-diagnose');if(ai){event.preventDefault();openAiDiagnosis(ai.dataset.runId);}});
$('#newPlan').onclick=()=>openPlanModal(); $('#newCase').onclick=()=>openCaseModal();
window.addEventListener('i18n:change',()=>{ updateShell(); render(); window.I18N.translateTree(document); });
refresh().catch(error=>{toast(`加载失败：${error.message}`,'error');$('#content').innerHTML=emptyHtml('无法加载本地数据','请确认服务器正在运行，然后刷新页面。');});
